// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_11: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.clone-companion","name":"Clone Companion","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your companion","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a duplicate of your companion, and the duplicate fights alongside its twin, mirroring the original's actions. The duplicate appears adjacent to your companion and has the same statistics.\n\nEach time you Command your companion, both your companion and its duplicate gain 2 actions. The duplicate always acts immediately after your companion and must use identical actions to the ones your companion used, in exactly the same order. However, it can use the actions differently, such as Striding to a different position or selecting a different target for a Strike. If the duplicate is unable to mimic an action, it performs the action without result and the action is wasted. The duplicate can't use any actions that can be used only a limited number of times per day.\n\nThe duplicate isn't truly alive and can't be healed in any way. If the duplicate ever reaches 0 Hit Points, it is instantly destroyed and clone companion immediately ends.","source":{"provider":"PAIZO","sourceId":"A0sMo1L0271yLeDA","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.confusing-colors","name":"Confusing Colors","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["illusion","incapacitation","manipulate","subtle","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A cloud of cascading, ever-changing colors manifests in the air. Creatures are while inside the cloud, as are those within 20 feet of the cloud's area. A creature must attempt a Will save if it is inside the cloud when you cast it, enters the cloud, ends its turn within the cloud, or uses a or Interact action on the cloud. A creature currently affected by the cloud doesn't need to attempt new saves.\nSuccess The creature is unaffected.\n\nFailure The creature is for [[/r 1d4 #rounds]]{1d4 rounds}.\n\nCritical Failure The creature is for [[/r 1d4 #rounds]]{1d4 rounds}. After the stunned condition ends, the creature is confused for the remaining duration of the spell.","source":{"provider":"PAIZO","sourceId":"uEyfLoFQsRKBRIcB","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.control-weather","name":"Control Weather","kind":"RITUAL","rank":8,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"4d12 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Survival","secondaryCasters":1},"description":"Area 2-mile-radius circle centered on you\n\nYou alter the weather, making it calm and normal for the season or choosing up to two effects based on the season.\n\n- Spring drizzle, heat, hurricane, sleet, thunderstorm, tornado\n\n- Summer drizzle, downpour, extreme heat, hail, heat\n\n- Autumn cold weather, fog, mild heat, sleet\n\n- Winter blizzard, mild cold, extreme cold, thaw\n\nYou can't specifically control the manifestations, such as the exact path of a tornado or the targets of lightning strikes.\n\nCritical Success You change the weather as desired and can affect a larger area (up to a 5-mile-radius circle), or a longer duration (any number of additional d12 hours, up to 16d12).\n\nSuccess You change the weather as desired.\n\nFailure You fail to change the weather as desired.\n\nCritical Failure The weather changes in an unanticipated way, determined by the GM but generally as contradictory to your true desires as possible (for instance, a terrible storm emerges when you would prefer good weather).\n\nHeightened (9th) You can create unseasonable weather and contradictory weather effects, such as extreme cold and a hurricane. You can make the weather calm and normal weather for a different season or choose weather effects from any season's list.","source":{"provider":"PAIZO","sourceId":"XkDCzMIyc0YOjw05","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-demiplane","name":"Create Demiplane","kind":"RITUAL","rank":8,"rarity":"RARE","traits":["mythic","teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"9 days"},"cost":"precious materials worth a total value of 800 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic), Nature (mythic), Occultism (mythic), or Religion (mythic)","secondaryChecks":"Arcana, Nature, Occultism, Religion (whichever three aren't used for the primary check)","secondaryCasters":3},"description":"Few incantations are as renowned as the power to create worlds. To cast this ritual, you must be on the Astral Plane, the Ethereal Plane, or a plane that connects to one of the two. A demiplane created with this ritual exists on the Astral or Ethereal Plane. It can have the appearance of any mundane environment or structure, such as a glorious cathedral, a forest clearing, a comfortably furnished cavern, or anything else imaginable. All demiplanes have finite, unbreachable boundaries, which might resemble stone, wood, or something more unnatural, such as a wall of mist or unceasing void.\n\nDemiplanes have environmental conditions appropriate for the Universe, though the primary caster can dictate a general climate or light level as well as whether the demiplane experiences seasons or a day-night cycle. The demiplane has no native plants or animals, but they can be introduced, and plants will grow in a demiplane's light.\n\nWhen you first cast create demiplane, the casters are teleported to the demiplane. The demiplane has no direct access to other worlds, so or similar abilities are necessary to access it. As part of casting the ritual to create a new demiplane, you create a planar key to the demiplane that serves as an interplanar teleport locus for that demiplane. Most resemble ornate keys, but some take the form of maps, compasses, or dowsing rods.\n\nIf you have the original planar key to an existing demiplane and are also on that demiplane, you can cast this ritual again. Each time, you can either expand the demiplane's size or add one special trait or feature described below.\n- Bounteous The demiplane has a functional ecosystem with plants and animals appropriate to the environment. This ecosystem doesn't require any additional effort on your part to maintain.\n- Elemental The demiplane gains the air, earth, fire, metal, water, or wood planar essence trait.\n- Gravity The demiplane gains a gravity trait of your choice.\n- Key You create an additional planar key that can be used to access the demiplane with interplanar teleport and improve it with create demiplane.\n- Portal You create a permanent gateway between the demiplane and a single other location. You must spend the ritual's casting time constructing the gateway on the external side, which typically resembles an arch or doorway of some sort. The gate is always active, but it can be secured as you would any door.\n- Scope The demiplane can be unbounded instead of finite, though still with the same size.\nCritical Success You create a new demiplane whose area consists of 10 contiguous squares, each 100 feet on a side. The ceiling is 40 feet high. If modifying an existing demiplane, you can instead either add this area to the demiplane's size or add two special traits or features.\n\nSuccess As critical success, but the demiplane's area is two squares, each 100 feet on a side, with a ceiling 20 feet high. If modifying an existing demiplane, you can add one special trait or feature.\n\nFailure The ritual has no effect.\n\nCritical Failure Something goes horribly wrong, and all casters are teleported to an unknown but hostile plane.\nHeightened (10th) The ritual creates a square area 2,000 feet on a side, with a ceiling 60 feet high (or two contiguous areas of this size on a critical success). The cost of the ritual increases to 20,000 gp.","source":{"provider":"PAIZO","sourceId":"ZwwIUavMbEwcZz35","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deluge","name":"Deluge","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":40}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{},"areaFeet":10},"counteraction":false,"ritual":null,"description":"You unleash a catastrophic downpour in the area that vanishes an instant later. All flying creatures in the area descend 50 feet or until blocked by the ground or firm surface. Each creature whose descent was blocked by the ground or firm surface takes bludgeoning damage equal to the number of feet it fell (the creature does not also take falling damage) and is knocked . Creatures on the ground, including flying creatures forced to the ground by the spell, must succeed at a Reflex save or be pushed 50 feet away from the center of the area.\n\nFlimsy structures in the area collapse. The GM can determine other large-scale effects that result from the deluge.\n\nHeightened (+1) The area increases by 10 feet, and flying creatures fall an additional 10 feet.","source":{"provider":"PAIZO","sourceId":"8fEfjvC01gNclDKJ","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.desiccate","name":"Desiccate","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"any number of living creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"10d10","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"You pull the moisture from the targets' bodies, dealing 10d10 void damage. Creatures made of water (such as water elementals) and plant creatures use the outcome for one degree of success worse than the result of their saving throw. Creatures whose bodies contain no significant moisture (such as earth elementals) are immune to desiccate.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"M0jQlpQYUr0pp2Sv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.devour-life","name":"Devour Life","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","death","healing","manipulate","void"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"60","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"10"}},"counteraction":false,"ritual":null,"description":"You attempt to utterly consume the target's life force. The target takes 60 void damage with a basic Fortitude save. If this damage reduces the target to 0 Hit Points, it dies immediately. You regain Hit Points equal to half the void damage the target takes (after applying resistance and the like). Any excess healing is gained as temporary Hit Points, which you lose after 1 minute.","source":{"provider":"PAIZO","sourceId":"PgLvO8UNHSj5f61m","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.disappearance","name":"Disappearance","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud a creature from others' senses. The target becomes , but not merely to vision. The invisibility granted by disappearance applies to all precise senses an observer might have. It's still possible for a creature to find the target by Seeking using various senses, looking for disturbed dust, hearing gaps in the sound spectrum, or finding some other way to discover the presence of a creature that is otherwise undetectable.","source":{"provider":"PAIZO","sourceId":"wfleiawxsfhpRRwf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-armageddon","name":"Divine Armageddon","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","vitality","void"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"You call forth a divine cataclysm from your deity, destroying living and undead creatures in the area alike. Creatures in the area take 10d6 void damage and 10d6 alignment damage (good, evil, lawful, or chaotic), chosen from among the alignments your deity has. If your deity is true neutral, increase the void damage by 4d6 instead of dealing alignment damage. A creature harmed by vitality damage, such as one with void healing, takes vitality damage instead of void damage from this spell.\n\nYou can't cast this spell if you don't have a deity. This spell gains the trait corresponding to the alignment damage dealt.\n\nHeightened (+1) The damage increases by 1d6 void damage, 1d6 alignment damage, and 1d6 additional void and vitality damage for a true neutral deity.\n\n(@item.level+2)d6[void,(@item.level+2)d6[spirit]|traits:spirit]{Leveled Void + Spirit Damage}\n\n(@item.level+2)d6[vitality,(@item.level+2)d6[spirit]|traits:spirit]{Leveled Vitality + Spirit Damage}\n\n((@item.level*2)-2)d6[void]{Leveled Void Damage}\n\n((@item.level*2)-2)d6[vitality]{Leveled Vitality Damage}","source":{"provider":"PAIZO","sourceId":"it4wx2mDIJDlZGqS","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-aura","name":"Divine Aura","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["aura","concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"allies in the area","area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Divine power wards the targets, granting each a +1 status bonus to AC and saves while in the area.\n\nChoose an alignment your deity has (chaotic, evil, good, or lawful). You can't cast this spell if you don't have a deity or your deity is true neutral. This spell gains the trait of the alignment you chose. The bonuses granted by the spell increase to +2 against attacks by-and effects created by-creatures with an alignment opposite to the spell (lawful if you chose chaotic, evil if you chose good). These bonuses increase to +4 against effects created by such creatures that attempt to impose the condition on a target of your divine aura, as well as against attacks made by creatures summoned by anything opposite in alignment to your divine aura.\n\nWhen a creature of opposite alignment hits a target with a melee attack, the creature must succeed at a Will save or be for 1 minute. It's then temporarily immune for 1 minute.\n\nThe first time you Sustain the Spell each round, the divine aura's radius grows 10 feet.","source":{"provider":"PAIZO","sourceId":"nsQvjNyg4Whw2mek","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-inspiration","name":"Divine Inspiration","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse a target with spiritual energy, refreshing its magic. If it prepares spells, it recovers one 6th-rank or lower spell it previously cast today and can cast that spell again. If it spontaneously casts spells, it recovers one of its 6th-rank or lower spell slots. If it has a focus pool, it regains its Focus Points, as if it had Refocused.","source":{"provider":"PAIZO","sourceId":"KtTGLbLG9nqMbUYL","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dream-council","name":"Dream Council","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental","sleep"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"up to 12 creatures you know by name and have met in person","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"When you Cast this Spell, any targets-including you-can choose to immediately fall asleep. The spell ends for any creatures that don't choose to fall asleep. Sleepers join a shared dream, where they can communicate with one another as though they were in the same room. Individual targets leave this shared dream upon awakening, and if all the targets awaken, the spell ends.","source":{"provider":"PAIZO","sourceId":"rwCh2qTYPA44KEoK","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.earthquake","name":"Earthquake","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":60}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"11d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You shake the ground, topple creatures into fissures, and collapse structures. The GM might add additional effects in certain areas. Cliffs might collapse, causing creatures to fall, or a lake might drain as fissures open up below its surface, leaving a morass of quicksand.\n- Shaking Ground The ground is difficult terrain, and creatures on it take a -2 circumstance penalty to attack rolls, AC, and skill checks.\n- Fissures Each creature on the ground must attempt a Reflex save at the start of its turn to keep its footing and avoid falling into 40-foot-deep fissures that open beneath it. The fissures are permanent, and their sides require successful athletics to Climb.\n- Collapse Structures and ceilings might collapse. The GM rolls a flat check for each (flat for a sturdy structure, flat for an average structure and most natural formations, flat for a shoddy structure, all adjusted higher or lower as the GM sees fit). A collapse deals 11d6 bludgeoning damage to each creature caught in it with a basic Reflex save. A creature falls unless it critically succeeds and falls into a fissure if it critically fails.\nHeightened (10th) You create a massive earthquake that can devastate a settlement. The range increases to half a mile and the area to a quarter-mile burst.","source":{"provider":"PAIZO","sourceId":"x7SPrsRxGb2Vy2nu","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.embodied-font","name":"Embodied Font","kind":"RITUAL","rank":8,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"magic items with a value of at least 2,000 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"the disembodied wildspell associated with the primary caster","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"skill corresponding to the target's casting tradition (trained)","secondaryCasters":0},"description":"You place the magic items into a neat pile and attempt to draw out their power to form a new body that the target can inhabit.\nCritical Success The target materializes within range, with full Hit Points, 1 Mythic Point, and as if having just completed daily preparations.\n\nSuccess As critical success, but all the target's spells and spell slots are expended.\n\nFailure As success, but the target is Clumsy 1, Drained 1, Doomed 1, and Enfeebled 1 for 1 week.\n\nCritical Failure The ritual fails and can't be attempted again for that target for 1 week. The magic items are still consumed.","source":{"provider":"PAIZO","sourceId":"HBxsMKXzZM0HviEE","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.encroaching-woods","name":"Encroaching Woods","kind":"RITUAL","rank":8,"rarity":"UNCOMMON","traits":["plant"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"a section of forest no larger than 1,000 square feet","area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Survival, Warfare Lore","secondaryCasters":2},"description":"You entreat the spirits of a nearby wood to cloak the movements of you and your allies. Each day at dawn following the successful completion of the ritual, the trees and other plants of the affected area move up to 500 feet in a direction of your choosing. There must be enough open space for the trees to move into, maintaining the general shape and size of the affected area. Large fortifications, such as city walls, and inhospitable natural features, such as wide rivers, will stop the trees, but the forest can shape itself around small buildings and streams. The trees traverse the distance over the course of 5 minutes, which is slow enough for most creatures within the forest to move along with them if they desire. However, anyone watching the forest from outside doesn't immediately perceive the movement unless they succeed at a Perception check against the ritual's casting DC. After this movement, the fact that the trees have changed their positions is obvious.\n\nDuring the ritual's duration, creatures within the forest are obscured to those outside the forest, as determined by the ritual's degree of success. This cover is usually used to stealthily approach opposing armies or settlements.\n\nOnce the ritual's duration has ended, the trees remain in their last location. They are affected normally by anything in their current environment that would prevent or stunt plant growth, such as a change of soil type or water quality, though such issues occur at the usual rate.\nCritical Success The affected trees sprout obscuring foliage, causing any creature within the forest to be undetected to creatures outside the forest. Each creature in the forest also gains greater cover.\n\nSuccess As critical success, but the creatures inside the forest are to creatures outside the forest and gain standard cover.\n\nFailure The ritual has no effect.\n\nCritical Failure The primal energy of the forest lashes out at you, cursing you to become one of the trees you sought to control. Each caster immediately gains the petrified condition, though they're solid wood instead of stone. Instead of the normal Hardness, a petrified caster has a Hardness of 5 and a weakness to axes equal to their level. The DC to counteract this condition is the ritual's casting DC.","source":{"provider":"PAIZO","sourceId":"BNkgZi1bcQcVmBHp","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.falling-sky","name":"Falling Sky","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 60-foot tall, 30-foot radius cylinder\nExtraordinary telekinetic pressure smashes down through the area, battering creatures within it to the ground. All flying creatures in the area descend to the bottom of the spell's area, taking twice as much bludgeoning damage as if they had fallen the distance moved, to a maximum of 60 falling damage if they fall 60 feet. They take this falling damage even if the spell's area is entirely in the air and they don't hit the ground, as they concuss against the bottom of the spell's area at great speed. Creatures on the ground and within the spell's area, including flying creatures forced to the ground, must attempt Fortitude saves.\nCritical Success The creature is unaffected, and if it was flying, it isn't knocked even though it took falling damage.\n\nSuccess The creature is knocked prone.\n\nFailure The creature is knocked prone and Stunned 2.\n\nCritical Failure The creature is knocked prone and stunned for 1 round.","source":{"provider":"PAIZO","sourceId":"vm9O7ne48NM72yrJ","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ferrous-form","name":"Ferrous Form","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","metal","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your body transforms entirely into flexible iron. You gain resistance 10 to physical damage, except adamantine. You're immune to death effects, disease, drained, , healing, nonlethal attacks, , poison, sickened, vitality, and void; any of those conditions you had when the spell is cast are suspended until the spell ends, then return with their remaining duration when the spell ends. While made of iron, you're subject to rusting effects like the spell.\n\nYour fist Strikes have a 1d10 damage die, and your metal spells deal one additional die of damage (of the same damage die and damage type the spell uses). You can cast as an innate spell; the casting is reduced from 2 actions to 1.\n\nIn this form, you don't need to breathe. Your Bulk doubles (to 6 if you're Small or 12 if you're Medium), and you become too dense to Swim in water, automatically sinking to the bottom. You can Dismiss the spell.\n\nHeightened (9th) The resistance increases to 15.","source":{"provider":"PAIZO","sourceId":"89Hj5QuqvcwVXcqj","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.freedom","name":"Freedom","kind":"RITUAL","rank":8,"rarity":"UNCOMMON","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"valuable oils and objects associated with the target worth a total value of 100 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"NONE"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic) or Occultism (mythic)","secondaryChecks":"Society","secondaryCasters":2},"description":"You perform a ritual to free a creature imprisoned, petrified, or otherwise put into stasis by any magical effects. You free them from all such effects, even effects like that don't have a duration, as long as freedom's spell rank is equal to or higher than the effect's spell rank. To perform the ritual, you must be within 10 feet of the target, or within 10 feet of the place where the target was imprisoned (in the case of effects that trap the creature in an unreachable prison, like the oubliette form of imprisonment). You must know the name of the creature and details of its background; if the creature isn't a close associate, a failure or critical failure on a secondary society check reduces even a critical success on the primary check to a failure.\nCritical Success You free the target from all magical effects imprisoning it, petrifying it, or putting it into stasis. It gains a +1 status bonus to saving throws to resist those same magical effects for 1 week.\n\nSuccess You free the target from all magical effects imprisoning it, petrifying it, or putting it into stasis.\n\nFailure You fail to free the target.\n\nCritical Failure The magical effects imprisoning the target, petrifying the target, or putting it into stasis affect you and all secondary casters.","source":{"provider":"PAIZO","sourceId":"4ddJSjC9Zz5DX0oG","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hidden-mind","name":"Hidden Mind","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Powerful wards hide a creature from magic that would spy on it or affect its mind. The target gains a +4 status bonus to saves against mental effects. Hidden mind attempts to counteract any detection, revelation, and scrying effects as if its spell rank were 1 higher than its actual rank. On a success, the effect functions normally except that it detects nothing about the target and its possessions. For instance, detect magic would still detect other magic in the area, but not any magic on the target.","source":{"provider":"PAIZO","sourceId":"C2w3YfBKjIRS07DP","book":"Pathfinder GM Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.holy-host","name":"Holy Host","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","holy","incarnate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"In stories, armies with just and righteous causes win with little difficulty, conquering unholy legions. However, many holy armies know that an extra hand never hurts in the fight to exterminate cruelty and unholy forces, and they might call upon the assistance of a holy army. The holy army occupies the space of a Huge creature. When you Cast this Spell, choose one of the holy militaries below to summon.\n- Agathions Speed 30 feet\n- Arrive (fire) Pranks for All A squadron of procyals arrives, eager to see your enemies learn their lesson in this fight. All enemies in a take 8d6[fire|options:area-damage|traits:fire] damage (reflex save) as the procyals bombard them with popping firecrackers\n- Depart Parting Lesson (emotion, mental) The procyals laugh uproariously as they leave, each throwing out a piece of unrelated advice to a nearby enemy. Enemies in a take 4d6[mental|options:area-damage|traits:emotion,mental] damage (will save). On a failure, a creature is also Stunned 1. On a critical failure, they're Stunned 2.\n\n- Angels Speed 30 feet, fly 40 feet\n- Arrive (spirit) Flaming Truth A legion of balisses arrive in a burst of holy flame, dealing 8d6[spirit|options:area-damage] damage to all creatures in a with a fortitude save. On a critical failure, a creature is also for 1 round\n- Depart Hidden Departure With a plume of smoke, the balisses vanish, spreading a thick cloud of smoke in a . All creatures within the smoke are . Unholy creatures within the smoke are Enfeebled 2, and holy creatures within the smoke gain the effects of truesight and ignore the concealment granted by the smoke.\n\n- Archons Speed 30 feet, fly 60 feet\n- Arrive (spirit) Justice Prevails A battalion of aesras, also known as legion archons, swoop in to provide assistance. Enemies within a take 8d6[spirit|options:area-damage] damage (reflex save)\n- Depart (fire) Eyes of Judgment With one final examination of the battlefield, the aesras take their leave, but not before bringing down their fiery swords to create a corridor of sacred flame. Enemies in a take 4d6[slashing,2d6[persistent,fire]|options:area-damage] damage (reflex save).\n\n- Azatas Speed 30 feet, fly 80 feet\n- Arrive (auditory, sonic) Inspiring Song Kanya muses arrive to embolden your allies while pushing back your foes. Enemies in a take 6d6[sonic|options:area-damage|traits:auditory,sonic] damage (fortitude save). A creature that fails the save is also pushed 10 feet away from the kanyas. Allies in the emanation gain a +2 status bonus to attack rolls and saving throws, as well as +4 status bonus to damage rolls for the duration of the spell\n- Depart (emotion, fear, mental) Booming Finale With a thunderous chord that stirs the hearts of your forces, the kanyas depart. Enemies in a must attempt a will save. On a failure, they're Frightened 2, and on a critical failure, they're Frightened 3 and for 1 round. Allies in this cone regain (4d10+16)[healing|traits:emotion,fear,mental] Hit Points.\n\n- Garudas Speed 25 feet, fly 60 feet\n- Arrive Swooping Dive A battalion of garudas sweep through enemy lines, dealing 6d10[slashing|options:area-damage] damage to enemies in a (reflex save)\n- Depart Winds of Freedom The garudas flap their wings in tandem, focusing on a within 60 feet of them. All allies in that area gain a +1 circumstance bonus to all skill checks and DCs for 1 round, and enemies must succeed a reflex save or be knocked .","source":{"provider":"PAIZO","sourceId":"BINaRykHRLGn4Qfm","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hypnopompic-terrors","name":"Hypnopompic Terrors","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","emotion","fear","illusion","incapacitation","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 10 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"O3qtZtTquCRAFJRB","formula":"6d12","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send a wave of nightmarish visions crashing over your targets, leaving them paralyzed by fear. These visions inflict real wounds on vulnerable targets, dealing 6d12 mental damage. If you target a sleeping creature, it wakes up as it attempts the save but takes one degree of success worse than the result it rolled on its save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Frightened 2 and takes half the mental damage.\n\nFailure The target is frightened 2, is for 1 round, and takes the full mental damage.\n\nCritical Failure The target is frightened 2, is paralyzed for 2 rounds, and takes double the mental damage.","source":{"provider":"PAIZO","sourceId":"TvZiwZRianfTSbEg","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.impaling-briars","name":"Impaling Briars","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","manipulate","plant","wood"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":100}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"10d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The ground within the area transforms into a mass of dangerous briars that assault and impede your foes. When you Cast the Supell and the first time you Sustain it each turn on subsequent rounds, select one of the following effects to occur in the area.\n\n- Ensnare The briars clump around your foes, attempting to hold them in place. A foe within the area (or flying at most 20 feet above the area) must attempt a Reflex save. On a failure, it takes a –10-foot circumstance penalty to all Speeds for 1 round, and on a critical failure, it is for 1 round unless it Escapes.\n\n- Impede The briars twist and writhe, making the entire area difficult terrain.\n\n- Wall A appears in the area, lasting for 1 round. The wall is greater difficult terrain instead of difficult terrain.\n\nIn addition, once per round you can direct the briars to impale any target in the area (or flying up to 20 feet above the area) that you can see by using a single action, which has the concentrate and manipulate traits. Make a spell attack roll. On a success, the target takes 10d6 piercing damage and takes a –10-foot circumstance penalty to all Speeds for 1 round; on a critical success, the target is Immobilized for 1 round unless it Escapes.","source":{"provider":"PAIZO","sourceId":"oGV6YdpZLIG4G4gH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.imprisonment","name":"Imprisonment","kind":"RITUAL","rank":8,"rarity":"UNCOMMON","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"reagents to construct the magical prison worth a total value of 800 gp × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature of up to 16th level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic) or Occultism (mythic)","secondaryChecks":"Crafting, Society","secondaryCasters":6},"description":"You perform a ritual to imprison a creature in one of several forms. While some versions of this ritual offer all the forms, others include only a single form or only a few of them. Whichever form you use, the effect can't be counteracted, though it can be ended by . Some forms of imprisonment can be ended by other means. Because the ritual requires the target to remain within 10 feet at all times, it typically requires you to subdue the target first.\n- Chains You bind the creature with chains, rendering it unable to use any actions other than to speak. Other creatures that attempt to approach, harm the chains, or free the trapped creature in any way must succeed at a Will save or be unable to do so forever. The chains have Hardness equal to 5 × the imprisonment ritual's spell rank and double that many Hit Points. Destroying the chains frees the target.\n- Prison You render the creature completely unable to leave a particular confined area or structure of your choice, such as a jail cell or sealed cave. The magic also prevents the creature from damaging its prison, either directly or indirectly, to break free. If the creature's prison is entirely destroyed by some external force, the creature is freed, though for some larger or natural prisons, this might be unfeasible.\n- Slumber You put the creature into an eternal sleep. This is a sleep effect. The creature ceases aging and doesn't require food or drink. A single sincere physical display of affection from a creature who genuinely loves the target—whether romantically, filially, or otherwise—frees it from the slumber.\n- Temporal Stasis You send the creature into a state of suspended animation outside the flow of time. The creature doesn't grow older and can't be affected by any effect from within the normal timestream. While casting this ritual, you can optionally name any amount of time for the stasis; after this duration elapses, the stasis ends. Unlike other forms of imprisonment, temporal stasis can be counteracted by a or spell.\n- Object (9th or 10th rank) You either shrink the creature to an inch in height or transform it into an insubstantial form whose body trails away into wisps below its head. Either way, you trap it inside a bottle, gem, jar, lamp, or similar container. The creature ceases aging and doesn't require food or drink. The creature is still aware of its surroundings and can move within the container and speak, but it can't use any other actions. Destroying the container kills the target rather than freeing it.\n- Oubliette (10th rank only) You entomb the target in a state of suspended animation deep beneath the surface of the ground and out of tune with reality so that it can't be reached by any means. You also prevent most magic from revealing the location where the imprisonment occurred. Powerful magic, such as the ritual, can reveal the location of the imprisonment, but even such magic can't free the target from the oubliette; only a 10th-rank freedom ritual can do so.\n\nCritical Success You imprison the target. You can either use a form of imprisonment that usually requires a spell rank 1 higher than your ritual or impose an –2 circumstance penalty to any checks for freedom rituals that would free the creature.\n\nSuccess You imprison the target.\n\nFailure You fail to imprison the target.\n\nCritical Failure You imprison yourself and the secondary casters in the same way you intended to imprison the target.\nHeightened (9th) You can use the object form of imprisonment in addition to the other options, and you can target a creature of up to 18th level. The base cost increases to 2,000 gp.\n\nHeightened (10th) You can use the object and oubliette forms of imprisonment in addition to the other options, and you can target a creature of up to 20th level. The base cost increases to 6,000 gp.","source":{"provider":"PAIZO","sourceId":"2CNqkt2s2IYkVnv6","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.medusas-wrath","name":"Medusa's Wrath","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make an attack filled with a medusa's petrifying power. Make an unarmed Strike with the following additional effects.\nCritical Success The target is Slowed 2 and must attempt a Fortitude save at the end of each of its turns; this ongoing save has the incapacitation trait. On a failed save, the slowed condition increases by 1 (2 on a critical failure). A successful save reduces the slowed condition by 1. When a creature is unable to act due to the slowed condition from medusa's wrath, it is permanently. The spell ends if the creature is petrified or the slowed condition is removed.\n\nSuccess As critical success, but the target is initially Slowed 1","source":{"provider":"PAIZO","sourceId":"wTYxxYJWN348oV15","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.migration","name":"Migration","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"you and up to 5 willing creatures","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The targets naturally take on animal forms most fitting their movement and environment. Each target gains a land, burrow, climb, fly, and swim Speed of 40 feet, and can transform into a Tiny or Small animal most appropriate for a given movement and environment. It also gains immunity to mild, severe, and extreme cold and heat, along with any other immunities common to the local wildlife, at the GM's discretion. In exploration mode, a target can move much faster, at a travel Speed of 20 miles per hour.\n\nA target can't Strike, cast spells, or use most manipulate actions in animal form, but it can resume its normal shape by Sustaining the spell. It can Sustain the spell again to resume animal form.","source":{"provider":"PAIZO","sourceId":"U0hL0LLaprcnAyzC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mimic-spell","name":"Mimic Spell","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Trigger A creature you're aware of within range Casts a Spell of the same tradition as mimic spell and of the same or lower rank.\nYou learn the secrets of a spell just by watching someone else cast it. Attempt to counteract the spell cast by the triggering creature. If the spell would be counteracted, you instead gain the ability to Cast that Spell without expending a slot.\n\nOn your next turn, you spend the same number of actions to Cast the Spell as the triggering creature, but you choose the targets (if any) and use your spell attack modifier or spell DC as appropriate. The spell is heightened to the same rank as mimic spell. The mimicked spell is of the same tradition as the spells you normally cast.\n\nIf you don't Cast the mimicked Spell by the end of your next turn, it is lost, unless you Sustain the knowledge of it. You can Sustain this knowledge for up to 1 minute, after which it is lost.","source":{"provider":"PAIZO","sourceId":"2a8wiTxvBhcMbMU5","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.moment-of-renewal","name":"Moment of Renewal","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"up to 6 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The targets experience a day's worth of recovery in an instant. Any detrimental effects that would be gone after 24 hours end, though this doesn't shorten the duration of any active spells affecting the targets. The targets regain Hit Points and recover from conditions as if they had taken 24 hours of rest, but they do not make their daily preparations again or gain any benefits of rest other than healing. The targets are then temporarily immune for 1 day.","source":{"provider":"PAIZO","sourceId":"4MOew29Z1oCX8O28","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.monstrosity-form","name":"Monstrosity Form","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform into the shape of a legendary monster, assuming a Huge battle form. You must have enough space to expand into or the spell is lost. When you cast this spell, choose phoenix, cave worm, or sea serpent. While in this form, you gain the beast trait (for phoenix) or the animal trait (for cave worm or sea serpent). You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 20 + your level. Ignore your armor's check penalty and Speed reduction.\n- 20 temporary Hit Points.\n- Darkvision.\n- One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +28, and you use the listed damage. These attacks are Strength based (for the purpose of the condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n- Athletics modifier of +30, unless your own modifier is higher.\nYou also gain specific abilities based on the type of monster you choose:\n- Cave Worm\n- Speed 40 feet, burrow 30 feet, swim 20 feet;\n- Melee 1 jaws (reach 10 feet), Damage 2d12+20 piercing;\n- Melee 1 stinger (agile, reach 10 feet), Damage 2d8+15 piercing plus 2d6 persistent poison;\n- Melee 1 body (reach 10 feet) Damage 2d8+20 bludgeoning;\n- Inexorable You automatically recover from the , , and conditions at the end of each of your turns. You're also immune to being and ignore difficult terrain and greater difficult terrain.\n\n- Phoenix\n- Speed 30 feet, fly 90 feet;\n- Melee 1 beak (reach 15 feet), Damage 2d6+12 piercing plus 2d4 fire and 2d4 persistent fire;\n- Melee 1 talon (agile, reach 15 feet), Damage 2d8+12 slashing;\n- Shroud of Flame (aura, fire, primal) 20 feet. You gain an aura of fire that extends out from you. A creature that enters or ends its turn within the aura takes 2d6 fire damage. A creature can take this damage only once per turn. You can activate or deactivate this aura with a Sustain action.\n\n- Sea Serpent\n- Speed 20 feet, swim 90 feet;\n- Melee 1 jaws (reach 15 feet), Damage 2d12+20 piercing;\n- Melee 1 tail (reach 25 feet), Damage 2d8+20 bludgeoning;\n- Spine Rake 2 (move) You extend your spines and Swim or Stride. Each creature you're adjacent to at any point during your movement takes 4d8+10 slashing damage (basic Reflex against your spell DC).\n\nHeightened (9th) You instead gain AC = 22 + your level, 25 temporary HP, attack modifier +31, increase damage by one damage die, and Athletics +33.","source":{"provider":"PAIZO","sourceId":"8AMvNVOUEtxBCDvJ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.musical-shift","name":"Musical Shift","kind":"SPELL","rank":8,"rarity":"RARE","traits":["auditory","concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a quick series of wrist flicks, music fills the air. While the music can be heard as if it were performed normally at a distance, creatures in the spell's area become affected in more significant ways. When you cast musical shift, select a key signature (to affect enemies) and a time signature (to affect allies) from the options below; all creatures within the area are affected as indicated. You can change the key signature or time signature as part of the action you take when you Sustain the spell.\n\nFlat (key signature) Whenever an enemy critically fails at a Strike, saving throw, or skill check, they fall in addition to other effects from the critical failure.\n\nNatural (key signature) Enemies take a –2 status penalty to attack rolls.\n\nSharp (key signature) Whenever an enemy takes piercing or slashing damage, they also take 2d6 persistent bleed damage.\n\nDouble (time signature) You and your allies become and can use the extra action each round only for , Stand, Step, or Stride actions.\n\nQuadruple (time signature) You and your allies gain a +2 status bonus to attack rolls.\n\nTriple (time signature) You and your allies gain a +2 status bonus to Armor Class and Reflex saving throws.","source":{"provider":"PAIZO","sourceId":"3ZxaIw1FOOocJboH","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.part-the-mists-to-paradise","name":"Part the Mists to Paradise","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","exploration","extradimensional","healing","manipulate","mythic"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you and up to 6 willing creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a pathway to paradise, visible only to you and your allies through a dense cloud of magical mist. You and the other targets within range are transported through this mist to an extradimensional paradise of idyllic geographical features. Creatures within this paradise don't need to eat or drink. For each minute you spend within this paradise, all creatures within experience the benefits of 24 hours passing, gaining the healing benefits of a full night's rest, as well as the elapse of any afflictions or spells with day-long intervals. However, for any afflictions or spells with intervals measured in shorter periods of time, only one of those intervals passes for every minute spent within the paradise. This means that at the end of a minute, a creature can attempt a saving throw against a disease whose interval is 1 day, a poison whose interval is 1 minute, and a harmful spell that allows a saving throw each round. Each saving throw attempted while within the paradise gains a +4 status bonus.\n\nYou and your allies can act normally while within the paradise and can use the time to cast spells, Refocus, or perform other exploration activities that take less than 10 minutes. When the spell ends, you and all other targets depart the paradise, returning through the mists to your previous locations or in the nearest unoccupied spaces. You can Dismiss this spell.","source":{"provider":"PAIZO","sourceId":"9sofMbyYL80shsHH","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pinpoint","name":"Pinpoint","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"UNLIMITED"},"target":"1 creature or object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You learn the name of the target's exact location (including the building, community, and country) and plane of existence. You can target a creature only if you've seen it in person, have one of its significant belongings, or have a piece of its body, such as a lock of hair. To target an object, you must have touched it or have a fragment of it. Pinpoint automatically overcomes protections against detection of lower rank than this spell, even if they would normally have a chance to block it.","source":{"provider":"PAIZO","sourceId":"CeSh8QcVnqP5OlLj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.polar-ray","name":"Polar Ray","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["attack","cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"10d8","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"You fire a blue-white ray of freezing air and sleet that deals 10d8 cold damage. Make a spell attack roll against the target.\n\nCritical Success The target takes double damage and is Drained 2\n\nSuccess The target takes full damage and is Drained 2\n\nHeightened (+1) The damage increases by 2d8","source":{"provider":"PAIZO","sourceId":"BKIet436snMNcnez","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.power-word-stun","name":"Power Word Stun","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["auditory","concentrate","mental"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You stun the target with an arcane word of power. Once targeted, the target is then temporarily immune for 10 minutes.\n\nThe effect of the spell depends on the target's level.\n\n- 13th or Lower The target is for [[/r 1d6 #rounds]]{1d6 rounds}.\n\n- 14th-15th The target is Stunned for 1 round.\n\n- 16th or Higher The target is Stunned 1.\n\nHeightened (+1) The levels at which each outcome applies increase by 2.","source":{"provider":"PAIZO","sourceId":"7PJSqUeKxTqOVrPk","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prismatic-wall","name":"Prismatic Wall","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"LINE","feet":60}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an opaque wall of shimmering, multicolored light. The wall is straight and vertical, stretching 60 feet long and 30 feet high. You must form the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. You can pass through the wall and ignore its effects. The wall sheds bright light out to 20 feet on each side (and dim light to the next 20 feet). Creatures other than you that come into the wall's light must attempt a will save; they're for 1 round on a success, for 1 round on a failure, and Blinded for 1 minute on a critical failure. They are then temporarily immune to the blinding effect for 1 hour.\n\nA prismatic wall has seven different layers, each a different color. Red, orange, yellow, and green have the effect of a 5th-rank spell of that color, and the others have the effect of a 7th-rank chromatic wall spell of that color. A creature that tries to pass through the wall must attempt a saving throw against each component wall. The effects take place simultaneously, so a creature turned to stone by the blue wall is still treated as a creature for the indigo and violet walls.\n\nThe wall as a whole is immune to counteracting effects of the wall's level or lower; each color must be counteracted by its specific spell, as described in chromatic wall. This must be done in order (red, orange, yellow, green, blue, indigo, then violet). A given color can't be affected until the previous color is counteracted. Counteracting a color wall removes that color's effect from the wall, and counteracting them all ends prismatic wall. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"iL6TujgTCtRRa0Y0","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prying-survey","name":"Prying Survey","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":120}},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create eight invisible, floating eyes, each about 3 inches in diameter, that scan the area around you, transmitting rough impressions of the environment. The eyes constantly examine and send you summaries of their findings. They are solid and can't move through barriers, and they don't follow routes that they fail to find while Searching. Any damage to an eye destroys it. When all eyes are destroyed, the spell ends.\n\nAs a single action, which has the concentrate trait, you can concentrate on a location within the area that an eye can reach. An eye travels to that location, and you Seek visually as if you were there. As an exploration activity, you can travel at half speed while continuing to concentrate on the eyes to gain the benefits of both the Scout and Search activities. With the eyes, you can check everything even if you are traveling faster than 300 feet per minute. The eyes use your Perception modifier. You can have only one prying survey in effect at a time.\n\nHeightened (10th) The area increases to a 500-foot emanation.","source":{"provider":"PAIZO","sourceId":"pt3gEnzA159uHcJC","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.punishing-winds","name":"Punishing Winds","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"CYLINDER","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area (continued) 30-foot-radius, 100-foot-tall cylinder\nViolent winds and a powerful downdraft fill the area, forming a cyclone. All flying creatures in the area descend 40 feet. The entire area is greater difficult terrain for Flying creatures, and difficult terrain for creatures on the ground or Climbing. Any creature that ends its turn Flying within the area descends 20 feet. Any creature pushed into a surface by this spell's winds takes bludgeoning damage as though it had fallen.\n\nThe squares at the outside vertical edges of the cylinder prevent creatures from leaving. These squares are greater difficult terrain, and a creature attempting to push through must succeed at an Athletics check or Acrobatics check to Maneuver in Flight against your spell DC to get through. A creature that fails ends its current action but can try again.","source":{"provider":"PAIZO","sourceId":"wi405lBjPcbF1DeR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.quandary","name":"Quandary","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","extradimensional","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transport the target into an extraplanar puzzle room of mysterious origin, locking them there. Once each turn as a single action, the target can attempt an Occultism check, Perception check, or Thievery check against your spell DC to solve the puzzle. Teleportation effects can't carry the target outside the puzzle room unless they can also traverse the planes, such as . When the spell ends, the target returns to the space it occupied when it was banished, or to the nearest space if the original is now filled.\n\nCritical Success The target solves the puzzle and escapes.\n\nSuccess The target is on the right path to the solution. If it was already on the right path, it solves the puzzle and escapes.\n\nFailure The target makes no progress toward a solution.\n\nCritical Failure The target makes no progress and, if it was on the right path, it no longer is.","source":{"provider":"PAIZO","sourceId":"Oj1PJBMQD9vuwCv7","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rainbow-fumarole","name":"Rainbow Fumarole","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","fire","incapacitation","light","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"CYLINDER","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 20-foot radius, 60-foot-tall cylinder\nMulti-hued flames break through cracks in the ground, reaching high into the sky and giving off dangerous fumes. When you cast the spell, roll 1d8 on the table below to determine the effects of the fumarole.\n\nAny creature caught inside the area of rainbow fumarole when you cast it takes the indicated damage with a basic Reflex save and, on a failure, takes any added effect listed. Creatures must also attempt a saving throw when they move through the spell's area or end their turn in it. Squares within the area of the rainbow fumarole are difficult terrain.\n[[/r 1d8]]{d8}\nColor\nDamage\nAdded Effect\n\n1\nRed\n50[fire,2d6[persistent,fire]|options:area-damage]{50 fire plus 2d6 persistent fire}\n—\n\n2\nOrange\n50[fire|options:area-damage]\nKnocked\n\n3\nYellow\n30[fire,20[bludgeoning]|options:area-damage]{30 fire plus 20 bludgeoning}\nPushed 10 feet\n\n4\nGreen\n20[fire,20[acid]|options:area-damage]{20 fire plus 20 acid}\nSickened 2\n\n5\nBlue\n30[fire|options:area-damage]\nfor 1 round\n\n6\nIndigo\n30[fire|options:area-damage]\nfor 1 minute\n\n7\nViolet\n30[fire|options:area-damage]\nSlowed 1 for 1 minute\n\n8\nAll\nChoose the color for each affected creature and use that color's damage and added effect; if a creature is affected again, you can choose a different color.\n—","source":{"provider":"PAIZO","sourceId":"0AZOIMRvZtePuGOw","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rite-of-the-red-star","name":"Rite of the Red Star","kind":"RITUAL","rank":8,"rarity":"RARE","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"TEXT","text":"all casters must be physically located within the stone ring of the Doorway to the Red Star"},"target":"Doorway to the Red Star","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 40 Arcana or Nature (master)","secondaryChecks":"DC 35 Arcana, Nature, Occultism, or Religion","secondaryCasters":0},"description":"You invoke the latent power within the Doorway to the Red Star through repetitive chanting and ritual movements in an attempt to open a portal to the planet Akiton.\n\nCritical Success The plaza hums with magical energy that vibrates bones, causes hair to rise as if in a static field, and graces the tongue with flavors both unbearably sweet and terribly foul. The crimson pillars of the Doorway itself begin to smoke, then shimmer with red light, while the air within the ring shifts and ripples as if in the throes of intense heat. A moment later, a portal to Akiton opens at the center of the standing stones. This portal is vertical and semi-circular, with a radius of 30 feet, and is filled with shimmering red energy-it doesn't provide a view of the other side. Any caster who steps through this portal is instantly transported to area B1 of the Hall of Reason on Akiton.\n\nSuccess As critical success, but the portal's magic is distressed and unstable. When a caster steps through the portal, they must attempt a fortitude save or become Drained 1 from the stress of the magical journey.\n\nFailure The portal fails to open, and all casters must attempt a fortitude save to avoid becoming drained 1 from the backlash of magical energy.\n\nCritical Failure As failure, but the misfire attracts the attention of a aeon which appears in the area at once and attempts to destroy the stones of the Doorway. After one round of attacks, it realizes the portal is beyond its ability to damage, and attempts to slay those who attempted to activate the portal in the first place.","source":{"provider":"PAIZO","sourceId":"fLiowSDQXo3vCQDh","book":"Pathfinder #173: Doorway to the Red Star","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shipwreck","name":"Shipwreck","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 vehicle","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gesture toward a vehicle and the vessel wrenches itself apart. It must attempt a Fortitude save.\nCritical Success The vehicle is unaffected.\n\nSuccess The vehicle becomes uncontrolled, and spaces within it become difficult terrain.\n\nFailure As success, plus the vehicle gains the broken condition. If it already had the broken condition, it's destroyed.\n\nCritical Failure The vehicle is reduced to 0 HP and is destroyed.","source":{"provider":"PAIZO","sourceId":"5uWwusDkfmOOlZjK","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spirit-song","name":"Spirit Song","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","spirit"],"traditions":["OCCULT","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"14d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your eldritch song sends pulsing waves of ethereal energy to attack creatures' spirits in the area, dealing 14d6 spirit damage that causes their bodies to momentarily freeze up from the hypnotic nature of the tune, depending on the result of their Fortitude save. The vibrating waves of spirit song penetrate into, but not through, solid barriers, damaging incorporeal creatures hiding in solid objects in the area but not passing onward to damage creatures in other rooms.\nCritical Success The creature takes no damage.\n\nSuccess The creature takes half damage and can't use reactions until the beginning of its turn.\n\nFailure The creature takes full damage, can't use reactions until the beginning of its turn, and is Stunned 1.\n\nCritical Failure The creature takes double damage, can't use reactions until the beginning of its turn, and is Stunned 2.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"Ht35SDf9PDStJfoC","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spiritual-epidemic","name":"Spiritual Epidemic","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","curse","manipulate","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You curse the target, sapping its spirit and leaving a contagious trap in its essence. The target must attempt a Will save. Any creature that casts a divine or occult spell on the target while it's affected is targeted by spiritual epidemic and must also attempt a Will save. The curse continues to spread in this way.\nCritical Success The target is unaffected.\n\nSuccess The target is Enfeebled 2 and Stupefied 2 for 1 round.\n\nFailure The target is enfeebled 2 and stupefied 2 for 1 minute and Enfeebled 1 and Stupefied 1 permanently.\n\nCritical Failure The target is Enfeebled 3 and Stupefied 3 for 1 minute and enfeebled 2 and stupefied 2 permanently.","source":{"provider":"PAIZO","sourceId":"MS60WhVifb45qORJ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.split-shadow","name":"Split Shadow","kind":"RITUAL","rank":8,"rarity":"RARE","traits":["illusion","shadow"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a precious possession or drop of blood from the creature to be duplicated, plus an ornate silver mirror worth 7,000 gp"},"targeting":{"range":{"kind":"NONE"},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (master, the check has the secret trait)","secondaryChecks":"Crafting, Deception, Performance, Society","secondaryCasters":4},"description":"You create a shadow double of the target by drawing energy directly from the Shadow Plane into a mirror and shaping it into an exact, quasi-real duplicate. When the mirror is shattered at the end of the ritual, the double steps out and comes into existence. The duplicate is a creature 3 levels lower than the target, with the same abilities as the target but reduced to the appropriate level. The shadow double looks identical to the target and has the same general mannerisms and personality. However, it only has a vague sense of the target's memories. It has a Deception modifier to Impersonate the target equal to the modifier of the secondary spellcaster who rolled the Deception or Performance check, with a +4 status bonus.\n\nCritical Success You bring the shadow double to life. It is under your absolute control. You gain a direct mental link with the shadow double and can spend an action to command it via this link, even at a distance.\n\nSuccess As a critical success, but there is no special link between you and the shadow double. You must spend an action to command it verbally or by some other means.\n\nFailure The ritual fails and has no effect.\n\nCritical Failure When the mirror is broken at the end of the ritual, the double appears but has the statistics of an elite greater shadow with all the knowledge of the target and the same Deception modifier a shadow double would have had if the ritual had succeeded.","source":{"provider":"PAIZO","sourceId":"Y9w4TYnb8cXU4UKY","book":"Pathfinder #185: A Taste of Ashes","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sudden-transposition","name":"Sudden Transposition","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"up to 2 creatures","area":{"shape":"EMANATION","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"R7H0EhBiGdZaVBMF","formula":"10d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrench the targets off their feet, forcefully teleporting them within the area. The creatures must each be able to fit in their new space, and their positions must be unoccupied, entirely within the area, and in your line of sight. Each target attempts a Fortitude save.\nCritical Success The target can teleport if it wants, but it chooses the destination within the area.\n\nSuccess The target is unaffected.\n\nFailure You teleport the target and choose its destination; the target takes 10d10 bludgeoning damage.\n\nCritical Failure You teleport the target and choose its destination; the target takes 20d10[bludgeoning] damage and is knocked .","source":{"provider":"PAIZO","sourceId":"2DFtBRLyYMPrimp7","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.summon-archmage","name":"Summon Archmage","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"3d4+3","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You briefly call forth the spirit of a legendary wizard from ages long past, which manifests as an immense humanoid figure (typically an elf or a human). The archmage occupies the space of a Large creature and has a Speed of 60 feet.\n\nArrive (evocation, force) Archmage's Amplification The archmage arrives in a fierce burst of magical force, automatically dealing 3d4+3 force damage to up to 5 creatures it chooses within 100 feet of it. Like , this can be blocked by the spell. The archmage also feeds magical power into some spells. Beneficial spells last longer due to the archmage's influence. When the remaining duration of a beneficial spell affecting you or one of your allies would decrease (usually at the start of the caster's turn), it doesn't decrease if the subject of the spell is within 100 feet of the archmage. This applies only if the spell's maximum duration was 3 rounds or longer.\n\nDepart (abjuration) Archmage's Rebuke The archmage drains the magic from your foes. Each of your enemies within 100 feet of the archmage must attempt a Will save. On a failure, the creature is Stupefied 2 for 1 round, and if it's currently benefiting from any spells of a lower level than summon archmage, the archmage can choose any one of them and end the spell.","source":{"provider":"PAIZO","sourceId":"JAaETUBg0xlttpCH","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.summon-deific-herald","name":"Summon Deific Herald","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3},"requirements":"You have a deity."},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your faith is strong enough to briefly summon a direct representative of your deity, such as the deity's herald. The herald occupies the space of a Huge creature and has a Speed of 60 feet. The effects of this spell depend on your deity's alignment.\n\n- Lawful Good Arrive (enchantment, good, lawful) Aura of Retribution While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Holy Smite The herald casts 5th-rank (choosing good) in a 100-foot emanation.\n\n- Neutral Good Arrive (enchantment, good) Aura of Redemption While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Merciful Healing The herald casts the 3-action version of 5th-rank with a radius of 100 feet. This spell targets only you and your allies.\n\n- Chaotic Good Arrive (chaotic, enchantment, good) Aura of Liberation While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Radiating Freedom The herald affects you and all your allies within 100 feet with . The duration is reduced to 3 rounds.\n\n- Lawful Neutral Arrive (abjuration, lawful) Defy Chaos You and each ally within 100 feet of the herald gain resistance 20 against spirit damage while the herald is present; Depart Order's Wrath The herald casts 5th-rank (choosing lawful) in a 100-foot emanation\n\n- Neutral Arrive (transmutation) Quickening Ripple You and each ally within 100 feet of the herald are while the herald is present, and can use the additional action to Step, Stride, or Strike; Depart Sapping Beam The herald casts 6th-rank in a 100-foot line.\n\n- Chaotic Neutral Arrive (abjuration, chaotic) Defy Law You and each ally within 100 feet of the herald gain resistance 20 against spirit damage while the herald is present; Depart Chaos Hammer The herald casts 5th-rank (choosing chaotic) in a 100-foot emanation.\n\n- Lawful Evil Arrive Aura of Iron While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Unholy Blight The herald casts 5th-rank (choosing evil) in a 100-foot emanation.\n\n- Neutral Evil Arrive Aura of Selfishness While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Infinite Despair The herald casts 5th-rank in a 100-foot cone.\n\n- Chaotic Evil Arrive Aura of Vengeance While within 100 feet of the herald, you and your allies gain the champion's reaction; Depart Weapon Hurricane The herald casts 5th-rank in a 100-foot cone, using d12 for the die size.","source":{"provider":"PAIZO","sourceId":"kIRWUBxocERjIBni","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-elemental-herald","name":"Summon Elemental Herald","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your meditation into the different elemental planes connects you to them deeply, and this connection allows you to summon a herald of an elemental lord. The herald arrives in the form of a natural disaster centralized on your enemies. The herald occupies the space of a Huge creature. When you Cast this Spell, choose one of the elemental heralds below to summon; if you're a divine spellcaster who worships an elemental lord, you must choose the option matching your deity's element. This spell gains the trait (air, earth, fire, metal, water, or wood) matching your choice.\n\n- Air Speed fly 60 feet; Arrive(air) Supercell Front The herald of air arrives in the form of a twisting tornado, with high-speed winds slamming into your enemies. Each enemy in a takes 10d8[bludgeoning] damage with a basic Fortitude save; Depart (air) Twister Downdraft Each enemy in a must attempt a Fortitude save. A creature that fails is knocked if it's on the ground or descends 40 feet if it's in the air. A creature that descends takes falling damage if this forced movement brings it to the ground.\n\n- Earth Speed 50 feet, burrow 30 feet; Arrive(earth) Tectonic Rise The herald of earth erupts from the ground, splitting it open in a . Each enemy in the emanation takes 10d6[slashing] damage from the flying debris with a basic Reflex save. Enemies who critically fail fall 30 feet into the crevasse, taking falling damage (the sides of the fissure require successful athletics checks to Climb); Depart (sonic) Plate Crash The herald of earth sinks back into the ground, and the sides of the crevasse slam together with a deafening blow, dealing 5d10[sonic] damage with a basic Fortitude save to all enemies in a . An enemy that critically fails is for 10 minutes.\n\n- Fire Speed 60 feet, fly 40 feet; Arrive(fire) Magma Flow The herald of fire flows into the area as living magma, dealing 10d6[fire] damage and 3d6[persistent,fire] damage to all enemies in a with a basic Reflex save; Depart(fire) Flame Vortex Each enemy in a 60-foot line takes 6d6[fire] damage and 3d6[persistent,fire] damage with a basic Reflex save as the fire herald whips into a fire pillar before vanishing.\n\n- Metal Speed 50 feet, fly 50 feet; Arrive(metal) Shard Cloud The herald of metal arrives as a cloud of metal shards and static electricity, dealing 4d8[slashing] damage and 4d12[electricity] damage to all enemies in a with a basic Reflex save; Depart(metal) Rust Mist The shards in the cloud rapidly rust and cling to enemies in the , dealing 10d6 damage to metal creatures and objects in the area with a basic Reflex save, ignoring Hardness. Unattended objects automatically critically fail this save.\n\n- Water Speed 40 feet, swim 60 feet; Arrive(cold, water) Hurricane Formation The herald of water forms as a miniature hurricane. Each enemy in a takes 4d10[bludgeoning] damage from the slamming rains and 4d10[cold] damage from the falling hail with a basic Fortitude save; Depart(cold, water) Cataclysmic Deluge The hurricane collapses into a rushing flood, dealing 6d8[bludgeoning] damage to all enemies in a with a basic Fortitude save. A creature that fails its save is pushed 20 feet away from the herald (or 40 feet on a critical failure).\n\n- Wood Speed 50 feet, burrow 30 feet; Arrive(plant, wood) Advantageous Roots The herald of wood bursts forth from the ground as a complex root system. Each enemy in a takes 6d10[piercing] damage with a basic Reflex save as the roots skewer its limbs and body. Each enemy that fails its save takes a –10-foot status penalty to its Speeds until the herald departs; Depart(plant, wood) Retreat to Soil The roots retreat into the ground, dealing 6d10[piercing] damage to each enemy in a with a basic Reflex save. Any creature with a penalty to Speeds from its initial save automatically takes 2d6[persistent,bleed] damage. The ground in the emanation is difficult terrain after the roots retreat.","source":{"provider":"PAIZO","sourceId":"kVNo3ga0lwLKPrem","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-irii","name":"Summon Irii","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cast your spell, whisper your words of power, and find that an irii is already here—indeed, they've always been here, and always were, and always will be. The temporal being occupies the space of a Medium creature and has a Speed of 60 feet and a fly Speed of 60 feet. When you Cast this Spell, choose whether it summons a fate irii or a fortune irii.\n- Fate The fate stands before you with its stained-glass wings and animal-headed gaze, floating eyes circling about it.\n- Arrive (fortune, prediction) Decree the Immutability of Time While within 30 feet of the fate, you and your allies who roll below 10 on a d20 for an attack roll, Perception check, saving throw, or skill check get a 10 instead.\n- Depart (misfortune, prediction) Observe the Inevitability of Destiny Each enemy within a must attempt a will save. If a creature fails its save, until the end of its next turn, any time it rolls above 10 on a d20 for an attack roll, Perception check, saving throw, or skill check, it gets a 10 instead.\n\n- Fortune The fortune stands before you with its golden horns and moth-scale wings, a sly smirk on its elfin face.\n- Arrive (fortune, prediction) Decree the Chaos of Infinity While within 30 feet of the fortune, you and your allies roll twice and take the higher roll on all damage rolls, Perception checks, and saving throws.\n\n- Depart (misfortune, prediction) Sunder Eternity's Authority Each enemy within a must attempt a will save. A creature that fails its save must roll twice and take the lower result on all damage rolls, Perception checks, and saving throws until the end of its next turn.","source":{"provider":"PAIZO","sourceId":"4ONjK2hoMBmuAAyk","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-warden-of-the-wild","name":"Summon Warden of the Wild","kind":"SPELL","rank":8,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You briefly call forth the spirit of one of the Wardens of the Wild, the legendary guardians of nature. The warden occupies the space of a Gargantuan creature. When you Cast this Spell, you summon a warden depending on the biome in which the spell is cast (for instance, summoning the Warden of Caverns and Burrows if summoned in a cave, canyon, or other underground environment). In an unnatural environment, the warden summoned depends on the region's most recent or similar natural biome, as decided by the GM.\n- : Speed 60 feet, burrow 100 feet; Arrive (earth) Obsidian Cage Obsidian stalagmites burst from the earth as the warden surfaces, impaling enemies and trapping them in stalagmites. Enemies on the ground within {40 feet} take 6d6[piercing] damage (reflex save). Creatures that fail their save become until they (the DC is your spell DC); Depart (earth) Blessing of the Depths The squares occupied by the warden remain disheveled and broken, becoming difficult terrain. The warden affects you and all your allies within {60 feet} with a and . The duration for both spells is reduced to 3 rounds, but the duration of mountain resilience isn't reduced when an affected target is hit by a bludgeoning, piercing, or slashing attack.\n- : Speed 120 feet; Arrive (illusion, mental) Idyllic Panorama The warden's presence unpredictably warps the appearances and perceived distances of creatures and obstacles around it. Each time an enemy within 40 feet of the warden attempts a Strike or Stride action, it takes 4d6[mental] damage (will save). On a critical failure, the creature Strikes a random target within reach or Strides in a random direction. On a critical success, the creature becomes temporarily immune for 1 round; Depart Fox's Insightful Trickery The warden affects you and all your allies within 60 feet with and . The duration for both spells is reduced to 3 rounds.\n- : Speed 60 feet, swim 120 feet; Arrive I Am the Tide If the warden is summoned in a body of water, it creates a churning whirlpool that deals 10d6[bludgeoning] damage to all creatures within {30 feet} (basic Reflex save). A creature that fails this save is pulled 15 feet closer to the warden (30 feet on a critical failure). If the warden is summoned outside of a body of water, it creates a wave of water that deals 8d6[bludgeoning] damage to all creatures within 30 feet (basic Reflex save). A creature that fails this save is pushed 10 feet away from the warden; Depart Acclimation to the Deep The warden affects you and your allies within 60 feet with and . The duration for both spells is reduced to 3 rounds, but a creature affected by feet to fins retains its normal land Speed.\n- : Speed 60 feet, fly 240 feet; Arrive Precipice Plummet The warden appears, flying downward from the sky and sends a shockwave where she lands. Creatures within {20 feet} take 10d6[sonic] damage (fortitude save). Creatures that critically fail their saves are Sickened 1; Depart (auditory) Song of the Skies The warden affects you and all your allies within 60 feet with and . The duration for both spells is reduced to 3 rounds.","source":{"provider":"PAIZO","sourceId":"l2YoqVPoFE7jpTLe","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.take-your-places","name":"Take Your Places","kind":"SPELL","rank":8,"rarity":"RARE","traits":["auditory","concentrate","linguistic","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 4 willing creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The scene would play out exactly as you envisioned it, if only the actors would respect their blocking. You instantly transport the targeted creatures and any items they're wearing and holding from their current space to an unoccupied space within range. You don't need to be able to see the destinations as long as you've been there in the past and know its relative location and distance from each target. Creatures affected by take your places are then temporarily immune to this spell for 1 minute.","source":{"provider":"PAIZO","sourceId":"bfdiKEZQLVvslcDi","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.touch-of-death","name":"Touch of Death","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","focus","incapacitation","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Make a melee unarmed Strike. If you hit and the target is alive, anytime during the duration, you can spend a single action, which has the auditory and concentrate traits, to speak a word of death that could instantly slay it. The target must attempt a Fortitude save.\nCritical Success The target survives, the spell ends, and the target is then temporarily immune for 24 hours.\n\nSuccess The target is Stunned 1 and takes 5*@item.level damage, the spell ends, and the target is then temporarily immune for 24 hours.\n\nFailure The target is Stunned 3 and takes 10*@item.level damage. The spell's duration continues, but the target is then temporarily immune for 24 hours against being killed by touch of death.\n\nCritical Failure The target dies.\n\nIf you cast touch of death again, the effects of any touch of death you had previously cast end.\nHeightened (+1) The damage increases by 10 on a failure, or 5 on a success.","source":{"provider":"PAIZO","sourceId":"Ovvflf5aFbmBxqq8","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.uncontrollable-dance","name":"Uncontrollable Dance","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target is overcome with an all-consuming urge to dance. For the duration of the spell, the target is and can't use reactions. While affected, the creature can't use move actions except to dance, using the Stride action to move up to half its Speed.\n\nCritical Success The target is unaffected.\n\nSuccess The spell's duration is 3 rounds, and the target must spend at least 1 action each turn dancing.\n\nFailure The spell's duration is 1 minute, and the target must spend at least 2 actions each turn dancing.\n\nCritical Failure The spell's duration is 1 minute, and the target must spend all its actions each turn dancing.","source":{"provider":"PAIZO","sourceId":"Jvyy6oVIQsD34MHB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.undermine-reality","name":"Undermine Reality","kind":"SPELL","rank":8,"rarity":"UNCOMMON","traits":["concentrate","illusion","incapacitation","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You lash a target with tendrils of shadow that steal some of its substance, making it quasi-real. As long as it is quasi-real, its Strikes deal half damage, it can't critically succeed at any skill check, and creatures attempting saving throws against its spells and effects get a result one degree of success better than they rolled. The target must attempt a Will saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess The target is quasi-real until the end of its next turn.\n\nFailure The target is quasi-real for 1 minute. At the end of each of its turns, it can attempt another Will save, ending the spell on a success.\n\nCritical Failure The target is quasi-real for an unlimited duration.","source":{"provider":"PAIZO","sourceId":"YiIOsc8T6E2iDxgh","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfettered-mark","name":"Unfettered Mark","kind":"RITUAL","rank":8,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare inks and needles worth a total value of 100 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature or self","area":null},"duration":{"text":"24 hours until the magic fades; the tattoo is permanent","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (master) or any (legendary)","secondaryChecks":"any","secondaryCasters":0},"description":"You tattoo the target with rare inks and create a magical tattoo called an unfettered mark. This particular version of the unfettered mark grants the target special powers to escape from the Black Whale and Stormholt (the demiplane that overlaps with the Black Whale). While Crafting is the easiest method for creating this tattoo, the artistry is less important than maintaining a feeling of freedom in your mind while performing the ritual. Because of this, you can use any skill as long as it holds a special significance to you. A ranger who is at home in the woods, for example, could use a Survival or Nature check while creating the tattoo. If the target already has a successful unfettered mark currently active, the magic fades from the old tattoo and is replaced by the results of the new ritual.\n\nThe ritual can be performed alone or with the aid of up to 10 secondary casters. Each secondary caster must tattoo themself with their own tattoo and pay the full ritual cost to participate. Creatures currently held captive in the prison have a special relationship with the ritual: for each month they spend drawing memories of home on the walls of their cell, they can reduce the total cost of the ritual by 50 gp.\n\nCritical Success The target and primary and secondary casters all gain the ability to leave Stormholt. To do so, they must leave the prison by swimming through the water or by riding in a vessel that is in contact with the water (such as a rowboat). When they reach the great whirlpool, they are pulled under as normal, but instead of being transported to the Flotsam Graveyard in Absalom, they are immediately transported (as ) to a location in Absalom of their choice. They also gain the benefits of , , and resistance to electricity 10 for the duration of the ritual.\n\nSuccess As critical success, except the affected creatures don't gain the benefits of water walk and water breathing.\n\nFailure You create the tattoo but fail to imbue it with magic.\n\nCritical Failure As failure, but the tattoo also creates an unwholesome bond with the demiplane of Stormholt. For 24 hours, the target and the primary and secondary casters gain a fishlike appearance and are covered in a slimy membrane. They gain the ability to breathe both water and air, but their skin quickly dries out when on land. After 1 hour on land they become Drained 1 and , conditions that can be removed only if they reenter water. Additionally, the membrane conducts electricity well, causing them to gain weakness 10 to electricity.","source":{"provider":"PAIZO","sourceId":"TYydobaLN4U7Ol3M","book":"Pathfinder #161: Belly of the Black Whale","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unholy-army","name":"Unholy Army","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate","unholy"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Reaching out to the legions of the wicked, you call upon them for assistance. They emerge, bubbling up from the ground, and stand to face your enemies, malevolent and ready for bloodshed. The unholy army occupies the space of a Huge creature. When you Cast this Spell, choose one of the unholy squadrons below to summon.\n- Asuras Speed 40 feet\n- Arrive Dance of Duality A legion of adhukaits arrive on the field, dancing and scurrying in and among your enemy's front line. All enemies in a take 10d6[slashing|options:area-damage] damage (reflex save) as the adhukaits slash at them with their kukris.\n- Depart Split Remembrance As the adhukaits begin to retreat, they argue about who did the most damage and decide to see which half is stronger. All enemies in a take 6d6[bludgeoning|options:area-damage] damage (fortitude save) as they're violently yanked by adhukaits. On a failure, a creature is Clumsy 1 for 1 minute (Clumsy 2 on a critical failure).\n\n- Daemons Speed 25 feet, fly 40 feet\n- Arrive (disease) Winds of Pestilence Leukodaemons fly into position, their wings beating with the dust of a thousand diseases of a thousand years. Enemies in a take 8d8[piercing|traits:disease|options:area-damage] damage (fortitude save). On a failure, a creature is also Sickened 1 (Sickened 2 on a critical failure).\n- Depart (disease) Remember Me The leukodaemons claw at your enemies with their infected nails. All enemies in a take 6d6[slashing|traits:disease|options:area-damage] damage (reflex save). On a failure, a creature is also Drained 1 (Drained 2 on a critical failure).\n\n- Demons Speed 25 feet\n- Arrive (fire) Fuming Entrance A legion of brimoraks arrive in clouds of thick black smoke. The army's space and every square in a is choked with burning ash and smog, making all creatures outside the smoke to creatures within it and all creatures within the smoke concealed to creatures outside the smoke and other creatures within it. This smoke lasts for 1 minute, and a creature who enters or begins its turn within the smoke must attempt a fortitude save or take 2d6[persistent, fire|options:area-damage] damage and become sickened 1 (3d6[persistent,fire] damage and sickened 2 on a critical failure).\n- Depart (fire) Swords of Flame The arson demons swing their flaming swords through your enemies' ranks. All enemies in a take (4d8)[slashing,(3d6)[fire]|options:area-damage] (reflex save). On a critical failure, a creature also takes 2d8[persistent,fire|options:area-damage] damage.\n\n- Devils Speed 25 feet\n- Arrive (spirit) Diabolic Infantry A legion of vordines swarm the battlefield. All enemies in a take 4d10[piercing,2d6[spirit]|options:area-damage] damage (reflex save) as the vordines impale them with their tridents.\n- Depart (nonlethal) Whipped and Tripped The devils' whips lengthen impossibly to flense flesh from soul. Enemies in two non-intersecting 40-foot lines take 6d8[bludgeoning|traits:nonlethal|options:area-damage] damage (reflex save). On a failure, a creature is also knocked . On a critical failure, it's also knocked prone and for 1 round.\n\n- Divs Speed 35 feet\n- Arrive (mental) Deceptive Delight A battalion of sepids arrives to torment your enemies. Enemies in a take 6d6[mental|options:area-damage] damage (will save). On a failure, a creature is for 1 round.\n- Depart (spirit) Battle Debris The sepids slam their falchions into the remnants of the chaos of battle, shattering bones, which explode out in a . All non-fiends in the area take 8d6[slashing,3d6[spirit]|options:area-damage] damage from debris (reflex save).\n\n- Qlippoths Speed 40 feet, climb 40 feet, fly 40 feet\n- Arrive (visual) Terrifying Scuttle A horde of gongorinans opens their maws to reveal the horror inside. All enemies in a must succeed at a will save or be sickened 2 (sickened 2 and for 1 round on a critical failure).\n- Depart Pincer Assault The gongorinans lash out at everyone. All enemies in a take 6d12[slashing|options:area-damage] damage (reflex save).\n\n- Velstracs Speed 25 feet\n- Arrive Chains of Pain A legion of sacristans emerges from the shadows, their barbed chains wrapping around enemy limbs to prevent all escape. Enemies in a must attempt a reflex save. On a failure, they take a –10-foot circumstance penalty to their Speeds and 2d6[bleed|options:area-damage] damage. On a critical failure they take a –20-foot circumstance penalty to their Speeds and 4d6[bleed] damage. This penalty to Speeds lasts until they recover from their persistent bleed damage\n- Depart Pleasant Screams The sacristans rip their chains from their victims, screaming in unison with their pain. Any enemies who failed the initial Reflex save during the sacristans' arrival take 4d8[piercing] damage (fortitude). In addition, everyone in a must attempt a will save. On a failure, they're Frightened 2 and for 1 minute (Frightened 3 and deafened for 1 minute on a critical failure); this effect has the auditory, emotion, fear, and mental traits.","source":{"provider":"PAIZO","sourceId":"HEuvZAjD1q0J8Y5i","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unrelenting-observation","name":"Unrelenting Observation","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 creature or object tracked and up to 5 other willing creatures","area":{"shape":"BURST","feet":20}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"This spell grants perfect sight based on scrying, allowing several willing targets to track the exact movements or position of one creature or object. Choose one target creature or object in the area to be tracked. It becomes the sensor for the spell. Up to five willing creatures of your choice in the area can see a ghostly image of this creature or object when it's out of their sight. They can perceive the creature or object perfectly, allowing them to ignore the or condition, though physical barriers still provide cover.\n\nThe tracking creatures can see the tracked creature or object through all barriers other than lead or running water, which block their vision. Distance doesn't matter, though the creature or object might move so far away it becomes too small to perceive. The tracking creatures don't see any of the environment around the target, though they do see any gear a creature is wearing or holding, and they can tell if it removes objects from its person.\n\nIf the target to be tracked is willing, the duration is 1 hour. If you try to track an unwilling creature, the target must attempt a Will save.\n\nCritical Success The creature or object is unaffected.\n\nSuccess As described, and the duration is 1 minute.\n\nFailure As described, and the duration is 1 hour.","source":{"provider":"PAIZO","sourceId":"y2cQYLr5mljDSu1G","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.whirlpool","name":"Whirlpool","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"CYLINDER","feet":25}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"8G9YlsK0PDFdlbdE","formula":"6d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"8G9YlsK0PDFdlbdE":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area 25-foot radius, 20-foot tall cylinder\n\nWith a spin of your hand, you create a large swirling vortex of storming waves. All squares in the whirlpool are difficult terrain. The constant churning of the fierce waves means that creatures are constantly tossed between areas of air and water, allowing both air- and water-breathing creatures to breathe within the vortex. Any creature with a swim Speed can Swim instead of Stride to move within the whirlpool; the DC to Swim within it is equal to your spell DC.\n\nAll creatures in the area take 6d10 bludgeoning damage as the waves crash into them. On subsequent rounds, the first time you Sustain the spell each round, the waves crash again with the same effect.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is drawn 10 feet toward the center of the whirlpool.\n\nCritical Failure The creature takes double damage and is drawn to the center of the whirlpool.\n\nHeightened (+1) The bludgeoning damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"0fjz8qc9NfkmWmJZ","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.whirlwind","name":"Whirlwind","kind":"SPELL","rank":8,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"CYLINDER","feet":15}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"5d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area (continued) 15-foot radius, 80-foot-tall cylinder\nPowerful winds coalesce into a devastating tornado. You can Cast this Spell only if you are outside or the ceiling is 80 feet or higher. All squares in the whirlwind are difficult terrain.\n\nAll creatures in the area take 5d10 bludgeoning damage as powerful winds and debris buffet them, with a Reflex save. Each time you Sustain the Spell, you can move the whirlwind up to 30 feet in a straight line. Each creature the whirlwind moves through takes the damage, also with a Reflex save. A creature can be affected by a whirlwind only once per round.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and rises 10 feet into the air. If it doesn't have a fly Speed, the creature gains one equal to its Speed until it either reaches the ground or ceases to be in the whirlwind's area, potentially falling when the spell ends or when it leaves the area.\n\nCritical Failure As failure, except the creature takes double damage and rises 20 feet into the air.\nHeightened (+1) Increase the bludgeoning damage by 1d10.","source":{"provider":"PAIZO","sourceId":"8hKW4mWQyLnkHVta","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.antimagic-artifice","name":"Antimagic Artifice","kind":"RITUAL","rank":9,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"reagents and oils worth a total value of 4,500 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"one inanimate object of 1 Bulk or less","area":null},"duration":{"text":"1 week (see text)","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (master), Nature (master), Occultism (master), or Religion (master)","secondaryChecks":"Arcana, Nature, Occultism, or Religion (whichever is used for the primary check) and Warfare Lore","secondaryCasters":2},"description":"You anoint a seemingly harmless item with the power to disrupt magic. As part of performing this ritual, you set a trigger for when the target object activates. The object remains enchanted for 1 week or until it's activated, whichever comes first.\n\nFor 10 minutes after the object is activated, magic is suppressed within an emanation centered on the object. Spells can't penetrate the area, magic items cease to function within it, and no one inside can cast spells or use magic abilities. Likewise, spells—such as dispel magic—can't affect the emanation unless they're of a higher rank than the ritual. Magic effects resume the moment they pass outside the emanation. For example, a caster outside of the emanation could target a fireball on a spot on the other side of the emanation, even if the line of effect passes through the emanation. A summoned creature winks out of existence if it enters the emanation but reappears if the emanation ends. Invested magic items cease to function, but they remain invested and resume functioning when they exit the emanation; the attribute boost from an apex item isn't suppressed within the field. Spells of a higher rank than antimagic artifice overcome its effects and can even be cast by a creature within the field.\n\nThe emanation disrupts only magic, so a +3 longsword still functions as a longsword. Magically created creatures (such as constructs with the magical trait) function normally within the emanation.\nCritical Success When triggered, the antimagic emanation has a radius of 100 feet. The ritual casters are unaffected by the emanation.\n\nSuccess When triggered, the antimagic emanation has a radius of 50 feet.\n\nFailure The ritual has no effect.\n\nCritical Failure The magic of the ritual backfires, scrambling the casters' minds. Each caster is Stupefied 4. The value of this condition is reduced by 1 for each day that passes, and it can't be removed or reduced by any other means.","source":{"provider":"PAIZO","sourceId":"LmtwcpYmrJfhGIZY","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.arcane-explosion","name":"Arcane Explosion","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","focus","force","manipulate","mythic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"9wSYsvMyZBn4SR20","formula":"16d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your body is temporarily converted into a ball of pure magic, rapidly exploding outward and reforming as a glowing sphere, after which you eventually regain your normal form. All creatures and objects in the emanation take 16d6 force damage (basic Fortitude saving throw). Creatures that fail are also pushed 10 feet directly away from you; creatures that can't complete this forced movement are knocked (but creatures who reduce this movement, such as with an ability or feat, don't fall prone). You become unfiltered magic; you gain the incorporeal trait, are immune to disease, poison, and precision damage, and gain resistance to all damage equal to your level (except force damage, spirit damage, and damage from Strikes with the property rune), with double the resistance against non-magical damage. While incorporeal, you can't Strike, Cast a Spell, or take any actions with the manipulate trait. Any creature that ends its turn adjacent to you while you're in this state takes 6d6[force] damage. You remain as pure magic until you Dismiss your new form, returning to your normal state at maximum Hit Points.","source":{"provider":"PAIZO","sourceId":"KY2xyMavZHAoG69D","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.astral-labyrinth","name":"Astral Labyrinth","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":80}},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You connect the entire area with an invisible maze of astral energy that interferes with dimensional and mental magic. Choose a point in the area that you can see when you cast this spell. Objects other than force effects and rare metals can't block this spell's area. Astral labyrinth attempts to counteract magical mental effects targeting or including anyone other than the caster in the area, though it has no effect on mental effects that began outside the area or before the spell was cast.\n\nIn addition, any creature that tries to depart or arrive in a location in the area by teleportation or extradimensional travel (including extradimensional spaces) must attempt a Will saving throw. Summoned creatures must attempt the save when they are summoned, but not when the summoning ends.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Stunned 1.\n\nFailure The creature is Stunned 1, you are mentally alerted that something has failed its save against this spell, and the creature arrives in the empty space closest to the point you chose instead of its intended destination.\n\nCritical Failure The creature is Stunned 3, you get a mental glimpse of its appearance, and the creature arrives in the empty space closest to the point you chose instead of its intended destination.\n\nHeightened (10th) You and creatures transported by your spells can't get a result worse than success on the saving throw to teleport into or out of the area.","source":{"provider":"PAIZO","sourceId":"BI4iwu3nApyIG0zY","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.beseech-arcanotheign","name":"Beseech Arcanotheign","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","incarnate","manipulate","mythic"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a whispered prayer or arcane sending, you conjure Arcanotheign, herald of Nethys. She's a storm of magic, half white and half black, roiling in a vaguely humanoid shape. She occupies the space of a Medium creature and has a Speed of 40 feet and a fly Speed of 60 feet.\n\nArrive (sonic) Storm's Unbridled Destruction Arcanotheign arrives with a flash of light and a cacophonous crash of colliding magic. All enemies in a take 8d12[sonic] damage with a basic Reflex save. A creature that critically fails is additionally for 10 minutes.\n\nDepart (electricity, healing) Flash of Brilliance Arcanotheign fires a powerful arcane blast at one target within 100 feet, dealing 5d12[electricity] damage with a basic Reflex save, and a powerful divine blast at one ally, healing 5d12 Hit Points. Then, Arcanotheign asks for payment in the form of a fond memory. If you pay this cost, you lose this memory, Arcanotheign gains this memory, and Arcanotheign whispers a secret into your mind; you can immediately on any subject at mythic proficiency.","source":{"provider":"PAIZO","sourceId":"wZ1rsLrWfYtMZfgv","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bilocation","name":"Bilocation","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You exist in two places at once. When you Cast the Spell, another copy of yourself appears in an adjacent square. During bilocation's duration, whenever you act, you can choose which of your selves does so, and whenever one of you uses a move action, you can both move. Your two selves share Hit Points, and any condition or effect on one affects both. If both of your selves are in the area of the same effect, or targeted by the same multitarget effect, you are only affected once. Even if you are reduced to 0 Hit Points or killed, both selves remain until the duration expires. Your link continues at any distance, even across planar boundaries. You can Dismiss the Spell, and if you do so, you choose which of the selves vanishes and which becomes you, allowing you to extricate one of your selves from a dangerous situation.","source":{"provider":"PAIZO","sourceId":"HHCgEEkeeShVQf8d","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blunt-the-final-blade","name":"Blunt the Final Blade","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["death"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"powdered dawnsilver and rare grave dirt worth 10,000 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 final blade","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion (legendary)","secondaryChecks":"Arcana, Crafting, Society, and the other skill not used for the primary check","secondaryCasters":3},"description":"You anoint the with powdered dawnsilver and grave dirt while speaking softly and carefully to the souls trapped within it. You create a mystical pathway for the souls to escape through and urge them to draw out the magic of the final blade with them as they depart.\n\nCritical Success As success, and the souls also grant a boon; the primary and secondary casters gain a +2 status bonus to saves against death and fear effects for the next year.\n\nSuccess The souls escape the final blade and peacefully pass on to their eternal rewards, as appropriate for each soul. The final blade is no longer magical; it can't store anymore souls and can be destroyed as a normal guillotine.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual goes horribly wrong. The souls within the final blade are released in a furious rush as a gray death that does its best to slay the ritual's casters and run amok among the living. The final blade retains it abilities and can continue to store souls.","source":{"provider":"PAIZO","sourceId":"LEMfFL551YB120RN","book":"Pathfinder Adventure: Night of the Gray Death","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.call-fluxwraith","name":"Call Fluxwraith","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You break a mirror and cast the shards into the air. Between their thousand fractured reflections, the fluxwraith appears—a thing of broken glass, broken time and broken lives. This undead creature occupies the space of a Medium creature and has a fly Speed of 60 feet.\n\nArrive (transmutation) Interrupted Lives\n\nEach enemy within a must attempt a Will save. If a creature fails its save, it is shunted into the future, vanishing now but automatically reappearing in the same location after [[/gmr 1d4 #rounds]]{1d4 rounds}. A creature can attempt an additional Will save at the end of each of its turns to end the duration. If its original space is occupied when it returns, the creature appears in the nearest unoccupied space. Since the creature is shunted forward in time, it doesn't experience any of the intervening time. Likewise, any effects on the creature with a duration don't decrease their duration, resuming when the creature reappears.\n\nDepart (divination, fear, mental, prediction) Dire Foresight\n\nEach enemy within a must attempt a Will save. On a failed save, the creature receives a brief vision of a deeply traumatic event in that lurks among the many possibilities of its future. The creature is Frightened 2 (Frightened 4 on a critical failure) and Slowed 1 while they are frightened.","source":{"provider":"PAIZO","sourceId":"i6GUJCWdNu2278oA","book":"Pathfinder Wake the Dead #3","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clone","name":"Clone","kind":"RITUAL","rank":9,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"7 days"},"cost":"rare laboratory supplies and reagents worth the target's level (minimum 1) × 100 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature up to 20th level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (legendary)","secondaryChecks":"Arcana, Medicine, Occultism","secondaryCasters":3},"description":"You collect hair, nail clippings, and samples of skin and blood from the target, who must be present throughout the ritual and can be one of the casters. You then use those samples to grow a duplicate of the target's physical form that will house the target's soul upon death. This duplicate is physically identical to the original creature.\n\nIn order to perform the ritual, you need an expanded alchemist's lab or a superior set of equipment. Once the ritual is successfully completed, the duplicate grows within the laboratory equipment for [[/r 2d4]] months. Though direct involvement isn't required during this period of growth, you must prevent any interference or interruption, or the ritual fails. When the duplicate is complete, the original creature's soul enters it as soon as their original body dies, or immediately if the creature died during the intervening months, as long as the soul is free and willing. If Pharasma has decided that the target's time has come or the target's soul is trapped or doesn't wish to return, the duplicate remains empty until the impediment is removed. While unoccupied, the inert duplicate must be preserved in suitable alchemical equipment to prevent it from rotting.\nCritical Success The cloning process is successful. When the soul occupies the completed clone, it is Clumsy 1, Drained 1, Doomed 1, and Enfeebled 1 for 1 week; these conditions can't be removed or reduced by any means until the week has passed.\n\nSuccess As critical success, but each condition value is 2.\n\nFailure You fail to form the clone.\n\nCritical Failure The clone appears to be successful, but something went horribly wrong. Once it grows to its full size, it can't hold the target's soul and instead houses a malevolent intelligence or an invasive creature (such as a powerful demon).","source":{"provider":"PAIZO","sourceId":"pZr1xrCpaSu6qrXU","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.crusade","name":"Crusade","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 4 creatures","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You issue a divine mandate or proclaim a cause to the targets. It can be to attain an item, claim a patch of land, slay a creature, war with a group, or be entirely peaceful. Your cause can't force the targets to harm one another or themselves. The targets become completely dedicated to that cause, depending on their levels. They choose their own actions, but they favor direct action over inaction or indirect action.\n\n- 13th or Lower The target is so dedicated to the cause that it pursues the cause to the death (unless you say otherwise).\n\n- 14th The target is dedicated to the cause, but the spell ends for the target if it's reduced to half its maximum Hit Points or fewer.\n\n- 15th As 14th, plus the target can attempt a Will save at the end of each of its turns to end the spell for itself.\n\nThe spell ends for all creatures if you or one of your allies uses a hostile action against a target, or when the cause is completed. The GM might determine this spell has alignment traits befitting the cause.\n\nHeightened (10th) The level for each category increases by 2.","source":{"provider":"PAIZO","sourceId":"xFY9RtDE4DQKlWNR","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.curse-of-calamity","name":"Curse of Calamity","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["curse","misfortune","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"3 days"}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"1 community, group, or settlement","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (mythic)","secondaryChecks":"Arcana, Nature, Religion","secondaryCasters":3},"description":"You condemn your targets to violent misfortune. At the GM's discretion, you can target a group of individuals within range who serve the same cause, such as a nation's army, or who have a shared identity, such as members of a single faith. You can also choose to target a settlement that's a village or town, or a neighborhood community within a larger settlement.\nCritical Success As success, and the targets experience extreme accidents that threaten life, limb, or other loss. The GM adjudicates these occurrences on a case-by-case basis, but in general, the population experiences a disturbing rise in unfortunate casualties.\n\nSuccess The targets experience misfortune during even routine tasks that result in minor injuries. This bad luck increases when you're close; the first time each round a target within 15 feet of you attempts an attack roll or skill check, they must roll twice and use the worse result.\n\nFailure The ritual has no effect.\n\nCritical Failure You unwittingly curse yourself. For the next 24 hours, each caster must roll all attack rolls and skill checks twice and use the worse result.","source":{"provider":"PAIZO","sourceId":"CGB3a9gJU5S8gjKk","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detonate-magic","name":"Detonate Magic","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 magic item or spell effect","area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"UteO1cYHknNfsDxQ","formula":"8d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause the magic within the target to dissipate in a destructive explosion. You attempt to counteract the target. If the attempt succeeds, an explosion of magical force deals 8d6 force damage with a basic Reflex save. If you successfully counteract the magic of an item, it's deactivated for 1 week (or destroyed on a critical success) and the explosion is a 5-foot emanation from the item. If you successfully counteract a spell, the effect ends and the explosion affects either all creatures in the spell's area or the target of the spell and all creatures in a 5-foot emanation around it.","source":{"provider":"PAIZO","sourceId":"kUSShxXzY1sPtJA0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dimensional-excision","name":"Dimensional Excision","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"2QdSH92yYPPq3Ru3","formula":"14d10","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false},{"id":"zJ797hWUtFCE3MIM","formula":"2d10","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You manipulate the boundaries between planes like a scalpel, using it to cut away portions of a creature's essence and banishing those portions to other realities and dimensions, afflicting the target deep lacerations or even severed appendages. The creature takes 14d10 damage (no damage type) and 2d10 persistent bleed damage and must attempt a Will save. If the target is not on its home plane, it takes a –4 status penalty to this save. A creature reduced to 0 HP has their entire body sectioned out and banished across multiple planes and dimensions, leaving nothing behind but their gear.\nHeightened (10th) The base damage increases by 2d10, and the persistent bleed damage by 1d10.","source":{"provider":"PAIZO","sourceId":"MFPvs0ARxtThYPFq","book":"Pathfinder #212: A Voice in the Blight","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.disjunction","name":"Disjunction","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 magic item","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Crackling energy disjoins the target. You attempt to counteract it. If you succeed, it's deactivated for 1 week. On a critical success, it's destroyed. If it's an artifact or similar item, you automatically fail.","source":{"provider":"PAIZO","sourceId":"ihbRf964JDXztcy3","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divinity-leech","name":"Divinity Leech","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You disrupt the connection between a divine caster or deific servitor and their deity, blocking their use of divine power. If the target fails its save, it is .\n\nFor the spell's duration, whenever the target casts a divine spell, you regain 6d6[healing] Hit Points and the target must attempt another Will save with the following effects.\nCritical Success The target is unaffected.\n\nSuccess Each target of the divine spell has an outcome one degree of success better than the result it rolled.\n\nFailure The divine spell is lost and target is Stunned 1.\n\nCritical Failure As failure, but the target is for 1 round.","source":{"provider":"PAIZO","sourceId":"T5Mt4jXFuh14uREv","book":"Pathfinder #162: Ruins of the Radiant Siege","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.embrace-nothingness","name":"Embrace Nothingness","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You empty your body of substance, becoming one with nothingness. You gain resistance to physical damage equal to your level. You move at half your normal Speed, but can move in any direction (including up and down). While moving, you have concealment. When it is not your turn and during your turn until you take an action with the move trait, you are . You can pass through solid inanimate objects as long as they are no more than 2 feet thick","source":{"provider":"PAIZO","sourceId":"mau1Olq58ECF0ZPi","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.falling-stars","name":"Falling Stars","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"5hgRJg7CfV9pZSUa","formula":"6d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"RrsNfz6nzSiUPvoY","formula":"14d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"5hgRJg7CfV9pZSUa":"1d10","RrsNfz6nzSiUPvoY":"2d6"}},"counteraction":false,"ritual":null,"description":"Area 4 40-foot bursts\n\nYou reach into the skies and call down an array of falling stars that explode upon colliding with the ground. Choose for the falling stars to be airbursts (sonic), asteroids (fire), comets (cold), or plasma (electricity). The spell gains the trait of the falling star type you chose. The four stars' central 10-foot bursts can't overlap. Each falling star deals 6d10 bludgeoning damage to each creature in the at the center of its area of effect before exploding, dealing 14d6 energy damage of the type you chose to each creature in its . A creature in any of the areas attempts one basic Reflex save against the spell no matter how many overlapping explosions it's caught in and can take each type of damage only once.\n\nHeightened (+1) The bludgeoning damage increases by 1d10, and the energy damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"jrBa9deU2ULFWvSl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.fantastic-facade","name":"Fantastic Facade","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["illusion"],"traditions":[],"casting":{"time":{"kind":"UNKNOWN","text":"1 week"},"cost":"mystical paint, elaborate veils, and powdered minerals worth 20,000 gp total"},"targeting":{"range":{"kind":"NONE"},"target":"1 settlement and its residents","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (legendary)","secondaryChecks":"Deception; Society or Survival; Stealth","secondaryCasters":3},"description":"Area up to 1 mile radius circle centered on you.\nYou draw a permanent series of complex illusions over the target settlement, choosing the look, sound, feel, and smell of the structures, terrain, and creatures within at the time the ritual is cast. You can alter the appearance of existing structures and creatures, and you can add illusory structures or creatures. For example, you could cause everything and everyone in the target area to appear green, create an illusory forest with a thick canopy that obscures the settlement from outside view, or make empty ruins seem inhabited and pristine. When you create the facade, you determine which illusory elements remain static (limited to basic natural movement, such as flags blowing in the breeze) and which follow a basic program (for example, a daily parade in the town square, complete with marching band). You're unable to alter the programs after you create the facade.\n\nYou can disguise creatures as you please, with the same effects as a 3rd-rank illusory disguise. If a creature affected by the facade leaves the area, any illusions affecting it fade after 1 day. You decide when casting the ritual whether newcomers are disguised by the illusions, and whether the disguise appears immediately or after a set period, up to 1 week.\n\nA creature that interacts with the target settlement in a way that would suggest or reveal the illusory nature of the facade, such as by trying to paint a building affected by the facade or climbing an illusory structure, can attempt to disbelieve the illusion. The illusions created by the spell are harmless, so an illusory river of lava wouldn't cause damage, nor could thorns on an illusory rose bush prick someone.\nCritical Success You create the facade as described, and you can alter the programs within your facade by spending 1 day to reprogram them.\n\nSuccess You create the facade as described.\n\nFailure Your illusions fail and the ritual has no effect.\n\nCritical Failure Your ritual produces unexpected and uncontrolled illusions different from what you had planned, such as unexpected and slowly shifting colors across the buildings, unpleasant smells, and creatures appearing as skeletons. These effects fade after 1 month.\nHeightened (10th) The cost increases to 100,000 gp and the radius can be up to 5 miles","source":{"provider":"PAIZO","sourceId":"nA0XlPsnMNrQMpio","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.foresight","name":"Foresight","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","mental","prediction"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain a sixth sense that warns you of danger that might befall the target of the spell. If you choose a creature other than yourself as the target, you create a psychic link through which you can inform the target of danger. This link is a mental effect. Due to the amount of information this spell requires you to process, you can't have more than one foresight spell in effect at a time. Casting foresight again ends the previous foresight. While foresight is in effect, the target gains a +2 status bonus to initiative rolls and isn't against creatures or when flanked. In addition, you gain the following reaction:","source":{"provider":"PAIZO","sourceId":"qsNeG9KZpODSACMq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forest-of-gates","name":"Forest of Gates","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TEXT","text":"1000 miles"},"target":"you and up to 6 willing creatures","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transport yourself and your allies to a peaceful extraplanar realm of towering trees, each of which holds a misty gateway to another location. When you Cast this Spell, you choose a specific destination within 1,000 miles that you can identify by its position relative to your starting position and by its appearance (or other identifying features). Incorrect knowledge of the location causes the spell to fail. You and your allies walk for 1 hour through the forest, and each of you regains Hit Points and reduces the value of any doomed or drained condition as if you'd taken a full night's rest. At the end of the journey, you attempt a arcana or nature check to find the correct gate to your desired location.\nCritical Success You and your allies arrive within 1,000 feet of your desired location.\n\nSuccess You and your allies arrive within 1 mile of your desired location.\n\nFailure You and your allies arrive within 10 miles of your desired location.\n\nCritical Failure You and your allies exit the forest within 1 mile of your original location.","source":{"provider":"PAIZO","sourceId":"oKC36WjFD1jgqUN5","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.implosion","name":"Implosion","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 corporeal creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"75","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"10"}},"counteraction":false,"ritual":null,"description":"You crush the target by causing it to collapse in on itself, dealing 75 damage. The first time each round you Sustain the spell, you must choose a new target to be subject to the same effect; the same creature can never be targeted more than once with a single casting of this spell. You also can't affect more than one creature per turn with implosion. You can't target a creature that's incorporeal, gaseous, or liquid, or otherwise lacking a solid form.\n\nHeightened (+1) The damage increases by 10.","source":{"provider":"PAIZO","sourceId":"4WS7HrFjwNvTn8T2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.linnorm-sting","name":"Linnorm Sting","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","fire","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d12","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You replicate the fiery venom of the tor linnorm and inflict an enemy with the dread dragon's debilitating bite. You deal 2d12[piercing] damage to the targeted creature and afflict it with tor linnorm venom. If the target takes piercing damage, they must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 8d6[fire] damage.\n\nFailure The target is afflicted with Tor Linnorm Venom at stage 1.\n\nCritical Failure The target is afflicted with tor linnorm venom at stage 2.\n\nTor Linnorm Venom (fire, injury, poison) Level 17\n\nMaximum Duration 10 rounds\n\nStage 1 8d6[fire] damage and Drained 1 (1 round)\n\nStage 2 12d6[fire] damage and Drained 2 (1 round)","source":{"provider":"PAIZO","sourceId":"ZMY58Yk5hnyfeE3q","book":"Pathfinder #160: Assault on Hunting Lodge Seven","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.magnetic-dominion","name":"Magnetic Dominion","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"target":"any number of creatures wearing metal armor, creatures made of metal, creatures that have the metal trait, and unattended metal objects","area":{"shape":"EMANATION","feet":100}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The roiling magnetic fields of the Plane of Metal radiate from you as you channel and reshape them at your merest thought. When you Cast this Spell, you can relocate each affected target to any other unoccupied space within the emanation. You can't move yourself in this way. An unwilling target can resist being moved with a successful Reflex save.\n\nThe creatures move all at once—after you know the results of all the saves, you determine which target occupies each space in whatever order you choose. You can move a creature into a space that was previously occupied by another creature so long as you also relocate the first creature elsewhere as part of the movement. If you move a target into the air, it descends to the ground harmlessly after being moved unless it chooses not to.\n\nYou can choose to be affected by an 8th-rank spell that lasts for the duration of magnetic dominion. Each time you Sustain the spell, you can move one creature in the emanation, with the same targeting restrictions and stipulations as above.","source":{"provider":"PAIZO","sourceId":"AsRd1gNRSkHDq2Jx","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.massacre","name":"Massacre","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","death","manipulate","void"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"9d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You unleash a wave of death to snuff out the life force of those in its path. Each living creature of 17th level or lower in the line must attempt a Fortitude save. If the damage from massacre reduces a creature to 0 Hit Points, that creature dies instantly. If massacre doesn't kill even a single creature, the void energy hungrily turns backward toward you, dealing an additional 30[void] damage to every living creature in the line (even those above 17th level) and 30 void damage to you.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 9d6 void damage.\n\nFailure The creature takes (ternary(gte(@item.rank,10),115,100))[void] damage.\n\nCritical Failure The creature dies.\nHeightened (10th) The spell can affect living creatures up to 19th level. Increase the damage to 10d6 on a success, and to 115 on a failure.","source":{"provider":"PAIZO","sourceId":"10VcmSYNBrvBphu1","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.metamorphosis","name":"Metamorphosis","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Harnessing your mastery of transformative magic, you hide forms within forms. You transform yourself into any form you could choose with a polymorph spell in your spell repertoire or that you could prepare of 8th-rank or lower (including any 8th-rank or lower heightened versions of spells you know). You gain 40 temporary Hit Points rather than the amount normally granted by the form.\n\nYou can Sustain the spell to enter a new form you haven't used during this metamorphosis. This replenishes your temporary Hit Points from this spell.","source":{"provider":"PAIZO","sourceId":"pswdik31kuHEvdno","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.natures-enmity","name":"Nature's Enmity","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"up to 5 creatures","area":{"shape":"BURST","feet":500}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Animals, plants, and fungi in the area turn against the targets. Each target suffers from the following effects as long as it remains in the area.\n- Vegetation springs up from every surface, giving each target a –10-foot circumstance penalty to its Speed any time it's adjacent to the plants and fungi.\n- Aggressive animals attack unpredictably. At the start of its turn, each target rolls a flat. On a failure, it's attacked by creatures that deal 2d10[slashing] damage. The target attempts a basic Reflex save and is for 1 round on any outcome other than a critical success.\n- The target loses any connection to nature or natural creatures. The target must succeed at a flat when casting any primal spell or the spell fails. Furthermore, animal, fungus, and plant creatures become hostile to it, even one with a strong bond to the target, such as an animal companion.\n\nThe GM might decide that you can't subject some creatures, such as an emissary of a nature deity, to the ire of nature.","source":{"provider":"PAIZO","sourceId":"Tc5NLaMu71vrGTJQ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.oceans-roar","name":"Ocean's Roar","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["mythic","water"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"1 or more boats or ships worth a total of 10,000 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"body of water no larger than a 7-mile radius area","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (mythic)","secondaryChecks":"Diplomacy, Sailing Lore, Survival","secondaryCasters":3},"description":"You invoke consciousness in a large body of water, such as a coastline, lake, or lagoon. An ancient elemental spirit awakens in the water, seeking instantly to defend itself from aggressors or punish trespassers. You must cast this ritual either directly above the surface of the water or completely submerged at the bottom of the body of water. Such spirits are known to crash ships, devastate shores, and drag enemies under the waves, but can also respond favorably to competent casters.\n\nThis new entity must be appeased by those who sail it. Appeasing the spirit requires a diplomacy or nature check at the ritual's casting DC. Those negotiating with the spirit might make offerings to gain the spirit's favor, but such reprieve is short in duration and must be attempted each time a vessel passes near. The nature of these offerings is subject to the GM's discretion.\nCritical Success As success, except the spirit looks kindly on the caster and those who travel with them. The spirit never takes hostile action against them or any vessel they travel on and increases their swim Speed or their vessel's Speed by 10 feet while within the affected area. Additionally, the spirit's Strike gains the ability with an Athletics modifier of +38.\n\nSuccess The spirit takes up residence in the body of water, defending it aggressively or attacking organized threats on adjacent shores. The spirit manifests as either a massive tsunami (GM Core 90, 96) that repeats every hour or a massive fist of water that can make a melee Strike every round against any target within the affected area. This Strike has a +33 modifier and deals 3d8+19 bludgeoning damage. The spirit can make this Strike against two targets within 30 feet, rolling once to attack and comparing the result against the AC of both targets.\n\nFailure The ritual has no effect, though tides and waves are more severe than normal for 24 hours.\n\nCritical Failure The ritual backfires, causing four Elemental Tsunamis to appear surrounding the casters and attack them for their insolence. If not defeated, the tsunamis remain for 1 week, attacking any waterborne vessels within the targeted area.","source":{"provider":"PAIZO","sourceId":"6WZgtQ2Iw9CTbv2c","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.one-with-the-land","name":"One with the Land","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","earth","manipulate","plant"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You merge with an adjacent natural feature with enough volume to fit you and your worn and held possessions, such as the ground or a large tree. Your merged form is visible within the feature, and creatures can target and attack you normally, though you have cover and can use it to Hide or Take Cover within the feature. You can cast spells while in the feature as long as they don't require line of effect beyond the feature. You can Dismiss the spell. While merged, you gain the following additional benefits.\n\n- You immediately become aware of the surrounding terrain features, and you gain tremorsense as an imprecise sense with a range of 200 feet.\n\n- You can make terrain vengeance Strikes by commanding plants, rocks, and other natural features to attack your foes. These are melee Strikes that use your spell attack roll, can target any creature within 60 feet of you, and deal 5d12 5d12[bludgeoning]{bludgeoning}, 5d12[piercing]{piercing}, or 5d12[slashing]{slashing} damage. You choose the damage type each time you make a terrain vengeance Strike.\n\n- By spending a single action, which has the concentrate trait, you can increase or decrease the environmental temperature changing it to either one step warmer than normal, one step colder than normal, or the normal temperature.\n\n- As a 2-action activity that has the concentrate trait, you can create or remove difficult terrain caused by natural terrain in a 20-foot burst within 200 feet. All of your alterations to the land end when the spell ends. Significant physical damage to the natural feature while you are inside it expels you and deals [[/r 10d6]]{10d6 damage} to you.","source":{"provider":"PAIZO","sourceId":"TbYqDhlNRiWHe146","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.overwhelming-presence","name":"Overwhelming Presence","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["auditory","concentrate","incapacitation","manipulate","mental","visual"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"any number of creatures","area":{"shape":"BURST","feet":40}},"duration":{"text":"until full tribute is paid","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself with supernatural splendor, appearing to be a god or similarly majestic being, with an appearance, regalia, and iconography of your choice. Targets must attempt a Will save. Regardless of the outcome, the target is then temporarily immune for 1 minute.\n\nCritical Success The target is unaffected.\n\nSuccess The target must pay tribute to you two times. Paying tribute requires that the target spend a single action, which has either the move trait (as they bow) or manipulate trait (as they offer up a token in their hands). They must pay tribute at least once on each of their turns, if possible. While affected, the target is by you and can't use hostile actions against you.\n\nFailure As success, but the target must pay tribute a total of six times.\n\nCritical Failure As failure, but the target must spend all its actions paying tribute, and they cannot take other actions until the tribute is fully paid.","source":{"provider":"PAIZO","sourceId":"fkDeKktdmbeplYRY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantasmagoria","name":"Phantasmagoria","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","death","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"any number of creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"1pyYgYlbN6qQ6aOV","formula":"16d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fill the targets' minds with endless images, like countless dreams and lives colliding with each other. The onrushing information deals 16d6[mental] damage to each target, depending on its Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and can't use reactions until the start of your next turn.\n\nFailure The target takes full damage and is until the start of your next turn.\n\nCritical Failure The target takes double damage and is confused for 1 minute.","source":{"provider":"PAIZO","sourceId":"MJx7DmjsWYzDZ3a4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.power-word-kill","name":"Power Word Kill","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["auditory","concentrate","death","mental"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"50","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utter the most powerful arcane word of power. Once targeted, the target is then temporarily immune for 10 minutes. The effect of the spell depends on the target's level.\n\n- 14th or Lower The target dies instantly.\n\n- 15th If the target has 50 Hit Points or fewer, it dies instantly; otherwise, it drops to 0 Hit Points and becomes Dying 1, or increases its Dying condition by 1 if it's already Dying.\n\n- 16th or Higher The target takes 50 damage; if this brings the target to 0 Hit Points, the target dies instantly.\n\nHeightened (10th) The levels at which each outcome applies increase by 2.","source":{"provider":"PAIZO","sourceId":"m3lcOFm400lQCUps","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.prismatic-shield","name":"Prismatic Shield","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","light"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Shield-sized shards of multicolored light manifest in the air around you, each rotating quickly to intercept attacks.\n\nMelee attacks against you impact a randomly colored shard, subjecting the attacker to a random effect from , with a saving throw of the type indicated in that spell.\n\nThe shards automatically block physical ranged attacks the size of a spear or smaller, such as arrows, bolts, and javelins. You gain a +2 circumstance bonus to your AC against attacks with larger ranged weapons.\n\nAny spell that targets you requires the caster to succeed at a counteract check against your spell DC, or it fails to affect you.","source":{"provider":"PAIZO","sourceId":"AlCFTjSBaCHuRHBv","book":"Pathfinder #162: Ruins of the Radiant Siege","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prismatic-sphere","name":"Prismatic Sphere","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a seven-layered sphere to protect an area. This multicolored sphere functions like a but is shaped in a 10-foot burst centered on a corner of your space. You must form the sphere in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost.","source":{"provider":"PAIZO","sourceId":"PngDCmU0MXZkbu0v","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.proliferating-eyes","name":"Proliferating Eyes","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature (see description)","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You implant an , magical eye sensor on the target's body. The eye has sight and vision, but no other special senses. The eye is highly contagious-the first two times the target touches another creature during the duration, the spell buds off an additional eye that implants itself on that creature, which can then bud off two eyes of its own. This process can propagate up to four times from the original target, for a potential maximum of 31 eyes if each affected creature touches two new creatures.\n\nYou can switch between perceiving through your own senses or the vision of any of the eye sensors using a single action, which has the concentrate trait. You always know how many eyes there are and can tell which original eyes budded off to make which new eyes, though you gain no special insight into the identity of the new targets other than what you can glean from spying on them.","source":{"provider":"PAIZO","sourceId":"coKiMMBLESkaLNVa","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.purify-tanglebriar","name":"Purify Tanglebriar","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["consecration"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"},"cost":"rare incense and offerings worth a total value of 2,000 gp"},"targeting":{"range":{"kind":"TEXT","text":"1-mile-radius circle centered on you"},"area":null},"duration":{"text":"see text","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature or Religion","secondaryChecks":"Arcana, Nature, Religion, Survival, or Tanglebriar Lore","secondaryCasters":3},"description":"You call upon the primal presence of the Fierani Forest and the elven legacy of Kyonin in an attempt to purify a portion of the blighted realm of Tanglebriar. Initially created by the elven wizard Aelthian in hopes of banishing Treerazer himself, this revision to that faulty ritual focuses instead upon the region he blighted rather than the nascent demon lord himself. Thus avoiding the catastrophic repercussions Aelthian experienced when he attempted to direct this magic against a foe too powerful to directly harm.\n\nThis version draws upon the ancient legacy of the forest itself by calling upon the remnants of primal spirits that remain locked away in Tanglebriar, bolstering them with elven magic. Successfully performing the ritual in an area in which Treerazer is currently located is more difficult, but the ritual's effects can weaken and distract him. If Treerazer is slain or banished, the effects of this ritual are longer lasting and less expensive—see \"Cleansing Tanglebriar\" on page 67 of this volume for more details.\n\nPurify Tanglebriar's primary caster must succeed at a DC 41 check, while the secondary casters must succeed at a DC 36 check. If Treerazer is present in the ritual's targeted area, these checks increase to DC 43 for the primary caster and DC 38 for the secondary casters, but if the primary caster wears the Viridian Crown, all checks for the primary and secondary casters are reduced by 5.\nCritical Success The region within the area grows less blighted for 1 month (during which time additional purify Tanglebriar attempts in this area have no additional effect). Greater difficult terrain becomes difficult terrain; difficult terrain becomes regular terrain, and hazardous terrain becomes non-hazardous. All DCs to , , and to resist environmental afflictions in the area are reduced by 4. Creatures allied with Treerazer take a –2 status penalty to Initiative checks within this region. If Treerazer is in the area when the ritual is performed, the party gains 2 Torment points toward weakening the demon lord and 2 Triumph Points.\n\nSuccess As critical success, but for 1 week (during which time additional purify Tanglebriar attempts in this area have no additional effect). Creatures allied with Treerazer take no penalty to Initiative checks. If Treerazer is in the area when the ritual is performed, the party gains 1 Torment Point and 1 Triumph Point.\n\nFailure The region is unaffected.\n\nCritical Failure The region is unaffected, and the magic itself becomes corrupted and backfires on the casters. Each caster takes 20d6[void] damage (fortitude save) as the purification energies sap away life itself. For 1 month, any attempt by that same primary caster to perform purify Tanglebriar increases its DCs by 5.","source":{"provider":"PAIZO","sourceId":"ZVdKM0HkgpWykrqf","book":"Pathfinder #212: A Voice in the Blight","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.qi-form","name":"Qi Form","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","focus","monk","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Drawing from deep wells of spiritual power, you take on a special qi form. In your qi form, your hair, feathers, skin, or scales change color and begin to glow.\n\nIn this form, you gain a fly Speed equal to your land Speed. Choose force, spirit, vitality, or void damage. All your Strikes deal 1d6 additional damage of the chosen type.\n\nYour entire body is also surrounded by a glowing corona of the same color as your inner qi; this is a light effect. Your corona is an aura in a 5-foot emanation that deals 2d6 damage of the chosen type to creatures who start their turn within the emanation. If the emanation overlaps with a darkness effect, the corona's glow attempts to counteract the darkness. Regardless of the outcome, the corona can't attempt to counteract that effect again for 1 day. You can Sustain to flare your corona out to become a 30-foot emanation or return the corona to a 5-foot emanation.\n\nIn your qi form, your emotions surge to the forefront, and it's difficult to moderate your attacks. Your weapons and unarmed attacks lose the nonlethal trait. You take a –2 status penalty to saves against emotion effects but gain a +2 status bonus to saves against all other mental effects.","source":{"provider":"PAIZO","sourceId":"YDMOqndvYFu3OjA6","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.resplendent-mansion","name":"Resplendent Mansion","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","structure"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a towering mansion up to four stories tall and up to 300 feet on a side. While Casting the Spell, you hold an image of the mansion and its desired appearance in your mind. The mansion can contain as many or as few rooms as you desire, and it's decorated as you imagine it. You can imagine a purpose for each room of the mansion, and the proper accouterments appear within. Any furniture or other mundane fixtures function normally for anyone inside the mansion, but they cease to exist if taken beyond its walls. No fixture created with this spell can create magical effects, but magical devices brought into the mansion function normally.\n\nYour mansion contains the same types and quantities of foodstuffs and servants as created by the spell.\n\nEach of the mansion's exterior doorways and windows are protected by spells. You choose whether each alarm is audible or mental as you Cast the Spell, and each has a different sound (for an audible alarm) or sensation (for a mental one), allowing you to instantly determine which portal has been used.","source":{"provider":"PAIZO","sourceId":"KPDHmmjJiw7PhTYF","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.seize-soul","name":"Seize Soul","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","manipulate","unholy"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2},"cost":"item worth at least the target's level x 100 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature that died within the last minute","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You trap the target's soul in the item before the soul can pass on to the afterlife. The item used to contain the soul can be anything as long as it's of the appropriate value. The item has AC 16 and its normal Hardness and HP. Destroying (not just breaking) an item or counteracting seize soul releases the soul to the afterlife.\n\nWhile the soul is in the item, the target can't be returned to life through any means, even powerful magic such as a ritual. If the item is destroyed or seize soul is counteracted on the item, the soul is freed. An item can't hold more than one soul, and any attempt wastes the spell.\n\nYou can also target an item that has had a soul trapped in it with a second casting of seize soul, which destroys the item and either releases the soul or relocates it to a different item, whichever you choose. This fails if the target is an artifact or the trapped soul is a creature of 19th level or higher.","source":{"provider":"PAIZO","sourceId":"GYmXvS9NJ7QwfWGg","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.storm-lord","name":"Storm Lord","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["air","concentrate","druid","electricity","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You are outdoors and aboveground."},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":100,"text":"100-foot emanation which affects you."}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"10d6","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The sky above you darkens in a matter of moments, swirling with ominous clouds punctuated by flashes of lighting. When you Cast the Spell and the first time you Sustain it each turn on subsequent rounds, select one of the following effects to occur in the area.\n\n- Calm No additional effect.\n\n- Fog Heavy fog rolls in, concealing the area with the effects of .\n\n- Rain Torrential rain falls from the sky, dousing ordinary flames. Creatures in the area take a -2 circumstance penalty to Acrobatics and Perception checks.\n\n- Wind Powerful winds buffet the area in all directions. Ranged attacks take a -4 circumstance penalty, and the area is difficult terrain for flying creatures.\n\nIn addition, once per round you can use a single action, which has the concentrate and manipulate traits, to call down a bolt of lightning, striking any target in range that you can see. You deal 10d6 electricity damage to the target; it must attempt a basic Reflex save. On a failure, it is also for 1 round.","source":{"provider":"PAIZO","sourceId":"XYhU3Wi94n1RKxTa","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.storm-of-vengeance","name":"Storm of Vengeance","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["air","concentrate","electricity","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":800},"area":{"shape":"BURST","feet":360}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A massive storm cloud forms in the air in a 360-foot burst. Beneath it, rain begins to fall, and gales impose a -4 circumstance penalty to physical ranged attacks and weapon ranged attacks, and the air in the area becomes greater difficult terrain for flying creatures. When you Cast this Spell and the first time each round you Sustain the Spell, you can choose one of the following storm effects. You can't choose the same effect twice in a row.\n\n- Acid Rain Each creature in the storm takes 4d8 acid damage with no saving throw.\n\n- Hail The storm deals 4d10 bludgeoning damage to creatures beneath it (basic Fortitude save).\n\n- Lightning Up to 10 bolts of lightning strike down, targeting creatures of your choice in the storm. No more than one bolt can target any one creature. Each bolt deals 7d6 electricity damage (basic Reflex save).\n\n- Rain and Wind Heavy rain and whipping wind reduce visibility and mobility, making the area under the storm cloud difficult terrain and making everything seen within or through the area .\n\n- Thunderclap Each creature in the storm must succeed at a Fortitude save or be for 10 minutes. A creature that succeeds is temporarily immune to thunderclaps from storm of vengeance for 1 hour.\n\nHeightened (10th) The range increases to 2,200 feet, and the cloud is a 1,000-foot burst.","source":{"provider":"PAIZO","sourceId":"r4HLQcYwB62bTayl","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-ancient-fleshforged","name":"Summon Ancient Fleshforged","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":250},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon an ancient Fleshforged, one of Nex's personal weaponized monstrosities unleashed in the first wars against Geb. It squeezes itself into its war form from time long forgotten, unleashing its wrath upon your foes. The Fleshforged occupies the space noted in the spell description. When you Cast this Spell, choose one of the Fleshforged below to summon.\n\n- Bone Breaker Size Gargantuan, Speed 40 feet, climb 100 feet\nArrive Skull Breaking Hum (evocation, sonic) The Bone Breaker appears in a shower of bone fragments. Its form is that of an immense titan of flesh and metal with long, muscular, twisted arms. The Bone Breaker releases a hum at a harmonic frequency that weakens bones in creatures' bodies. Each foe within an 80-foot emanation must attempt a Fortitude save. On a critical success, they're unaffected; on a success, they're Enfeebled 2 for 1 round; on a failure they're Enfeebled 3 for 1 minute; and on a critical failure, they're Enfeebled 4 for 10 minutes. A skeleton or other undead foe made almost entirely of bones treats their result as one degree of success worse than they rolled.\n\nDepart Bruising Departure The Bone Breaker pounds its long arms into the ground, creating a long shockwave. Each foe within a {100-foot-long, 10-foot-wide line} takes 8d12[bludgeoning] damage, with a basic Fortitude save.\n\n- Thorn Caller Size Gargantuan, Speed 100 feet\nArrive (evocation, light) Thorn's Guidance The Thorn Caller appears in a burst of light. The Thorn Caller's body is an ornate armored sphere with black panther masks surrounding a glowing light. The ball floats in the air due to six glowing, thornlike wings. Two clusters of bird heads emerge from both sides of the body with long necks that twirl together like tentacles. The Thorn Caller's burst of light illuminates all foes within 200 feet. The foes become and off-guard, and if they were , they become instead. These effects last until the Thorn Caller departs.\n\nDepart Thorn-Burst The Thorn Caller launches its thorned wings at various targets. Attempt spell attack rolls against up to 6 different targets within 300 feet. On a hit, the target takes 10d8[piercing] damage, double on a critical hit, half on a failure, and none on a critical failure.\n\n- The Thousand Size Medium (see below), Speed 30 feet\nArrive (emotion, enchantment, fear, mental) Disconcerting Arrival Select five spaces in range and summon a Medium-sized polyp of The Thousand in each of these spaces. The Thousand is an entity whose full scope is 1,000 polyps of oozing flesh, each physically separate but mentally part of a single creature. Not all 1,000 polyps have survived, and the spell summons five of them. Each creature within 10 feet of any of the polyps must attempt a Will Save. On a critical success, they're unaffected; on a success, they're Frightened 1; on a failure, they're Frightened 3; and on a critical failure, they're Frightened 4 and for 1 round\n\nDepart (illusion, mental) Violent Omen Each frightened foe within a 60-foot emanation of any of the five polyps takes 10d8[mental] damage, with a basic Will save.\n\n- Scion of Desiccation Size Gargantuan, Speed 100 feet, fly 100 feet\nArrive (necromancy, negative) Ashes to Ashes The Scion of Desiccation appears in a swirl of screaming wind, a gargantuan form of twisted flesh that's constantly flensed by gritty ash and dust, and just as constantly regenerating itself. Each foe within a 40-foot emanation takes 10d10 void energy damage, with a basic Fortitude save\n\nDepart (necromancy, negative) Dust to Dust Each foe within a 60-foot emanation must attempt a Fortitude save; they're Drained 2 on a failure or Drained 4 on a critical failure.","source":{"provider":"PAIZO","sourceId":"tgJTm276cikEL8vU","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-draconic-legion","name":"Summon Draconic Legion","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"10d8","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You momentarily summon an army of powerful dragons that unleash annihilating blasts as they descend upon your location. These dragons act as one and collectively occupy the space of a Gargantuan creature. They have a fly Speed of 100 feet. When you Cast this Spell, choose whether it summons chromatic or metallic dragons.\n\nArrive (evocation) Energy Annihilation The draconic legion breathes out two blasts of energy: a and a that can't overlap. Each creature in either of the areas takes 10d8 damage (basic Reflex save). The dragons choose the damage type of each breath weapon, depending on the category of dragons summoned. Chromatic dragons can choose cold, fire, or poison for the cone and acid or electricity for the line; metallic dragons can choose cold or fire for the cone and acid, electricity, or fire for the line.\n\nDepart Draconic Whirlwind The draconic legion strikes with fury, dealing 9d8[slashing] damage (basic Reflex save) to all enemy creatures in its location or within 20 feet.","source":{"provider":"PAIZO","sourceId":"2EIUqc8TCTQimggQ","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.telepathic-demand","name":"Telepathic Demand","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","incapacitation","linguistic","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature you've telepathically contacted before","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send the target a message of 25 words or fewer, and it can respond immediately with its own message of 25 words or fewer. Your message is insidious and has the effect of a spell, with the message substituting for the spoken suggestion. On a successful save, the target is temporarily immune for 1 day, and on a critical success, the target is temporarily immune for 1 month. You can target a creature only if you've previously been in telepathic contact with it before, such as via the telepathy spell.","source":{"provider":"PAIZO","sourceId":"ItZgGznUBhgWBwFG","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.trim-the-blight","name":"Trim the Blight","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":60}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"faJw2uvtNcCSSCQg","formula":"12d10","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a cone of shimmering energy that attempts to banish the influence of invasive, supernatural blight, such as that found in Tanglebriar. Blighted difficult terrain in the area becomes regular terrain, while blighted greater difficult terrain becomes difficult terrain; hazardous terrain in the area becomes nonhazardous. These effects persist for 1 hour.\n\nCreatures in the area that carry features of this blight (as determined by the GM, but automatically including all creatures with the fiend trait in this adventure) are trimmed as well, their supernatural infusion of blight being drained. These creatures take 12d10 spirit damage and must attempt a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature's reach with attacks is reduced by 5 feet (to a minimum of 5 feet) for 1 hour, they are Sickened 1 and Slowed 1 for 1 round.\n\nCritical Failure The creature's reach is reduced to 5 feet for 1 hour, they are Sickened 2 and slowed 1 for 1 minute.\nHeightened (10th) The spirit damage increases by 2d10, and 1 hour durations increase to 24 hours.","source":{"provider":"PAIZO","sourceId":"A7NXFVgENRVtYoe3","book":"Pathfinder #212: A Voice in the Blight","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.unblinking-flame-ignition","name":"Unblinking Flame Ignition","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","fire","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A foe reduces you to half your Hit Points or fewer.\n\nYou feel the most alive when pushed into a corner, as the insights and vision granted by the flame stoke into overdrive. Your body begins to emit a blazing aura of flames. You gain greater darkvision, low‐light vision, and the ability to see invisible creatures. You gain a fly Speed equal to your land Speed as you launch flame from your aura to soar through the sky. You become , and you can use the extra action each round only to Strike or using your flames. Any creature who starts their turn within 5 feet of you takes 1d12[fire] damage.","source":{"provider":"PAIZO","sourceId":"aFd00WT266VYPqOG","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unbreaking-wave-containment","name":"Unbreaking Wave Containment","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","focus","incapacitation","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"4 creatures","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"RmRLvyDCmUrdG9Qp","formula":"10d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You wrap enemies in four strands of water. When you cast the spell, make a spell attack roll against the targets. On a success, they're until the spell ends or they ; on a critical success, they're also until the spell ends or they Escape. Each target that's immobilized or restrained also takes 10d6 bludgeoning damage from the constricting waves, with a basic Fortitude save. The first time each subsequent round when you sustain the Spell, if all the targets aren't immobilized or restrained, make a spell attack roll against any targets who are free but remain within range, with the same effects as when you cast the spell, immobilizing or restraining them depending on your spell attack roll. Creatures who are immobilized or restrained take 10d6 bludgeoning damage with a basic Fortitude save.","source":{"provider":"PAIZO","sourceId":"axYqY70kYu2lN20R","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.undertaker","name":"Undertaker","kind":"SPELL","rank":9,"rarity":"RARE","traits":["concentrate","death","evil","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You point your finger toward the target and whisper an epitaph that promises to grace their gravestone in the near future. This spell works best when both you and the target are in contact with solid ground. If either is not in contact with the ground, the target gains a +2 circumstance bonus on their saving throw against the spell, and if both you and the target are not in contact with solid ground, the target gains this bonus and treats the result of their save as one degree of success better than the actual result. The target of undertaker can resist with a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes 40[void] damage. If the target is in contact with solid ground, the ground in the target's space shifts and shakes, and is treated as difficult terrain until the start of your next turn.\n\nFailure The target takes 80[void] damage. If the target is in contact with solid ground, the ground in the target's space churns and cracks open into an open but shallow grave. The target is knocked , and that space is treated as difficult terrain until the grave is filled in.\n\nCritical Failure The target takes 160[void] damage. If the target is in contact with solid ground, a grave opens beneath their feet and they fall prone within. The grave then forms a stone sarcophagus-like shell around the victim. This stone shell cannot be opened and must be broken; it has AC 10, Hardness 14, and 80 Hit Points. At the start of your next turn, the grave fills in with soil. If the victim dies while inside this grave, at the next sundown the victim transforms into an evil ghast as the sarcophagus crumbles, allowing the new undead to dig its way up to the surface.","source":{"provider":"PAIZO","sourceId":"z39jFoNJrobyn3MQ","book":"Pathfinder #184: The Ghouls Hunger","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfathomable-song","name":"Unfathomable Song","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["auditory","concentrate","emotion","fear","incapacitation","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"up to 5 creatures","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Fleeting notes of a strange and unnatural song fill the air, overtaking the mind. Each target must attempt a Will save when you cast the spell, and again the first time you Sustain this Spell each round. A creature needs to attempt only one save against the song each round, and you have to keep the same targets when you Sustain the Spell.\nCritical Success The target is unaffected, can't be affected on subsequent rounds, and is temporarily immune for 1 minute.\n\nSuccess The target is unaffected this round, but it can be affected on subsequent rounds.\n\nFailure Roll [[/r 1d4]] on the table below.\n\nCritical Failure Roll [[/r 1d4+1]] on the table below.\nResultEffect\n1The target is Frightened 2\n2The target is for 1 round\n3The target is Stupefied 4 for 1 round\n4The target is for 1 round\n5The target is for 1 round and Stupefied 1 for an unlimited duration","source":{"provider":"PAIZO","sourceId":"FmNDwqMEjeTEGPrY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfolding-wind-crash","name":"Unfolding Wind Crash","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["air","concentrate","focus","move"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"SkA0hnMkeRZeHBNT","formula":"18d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You jump up to 120 feet in any direction and then deal 18d6 bludgeoning damage to creatures within a 20‐foot emanation after you land, with a basic Reflex save. Creatures who critically fail are also knocked .\n\nHeightened (10th) The damage increases to 20d6.","source":{"provider":"PAIZO","sourceId":"XjNROFtWnwovhCsq","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.unspeakable-shadow","name":"Unspeakable Shadow","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","death","emotion","fear","illusion","manipulate","mental","shadow","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You alter a creature's shadow, transforming it into a terrifying monster out to devour the creature. The creature must attempt a Will save. A creature that has the frightened condition from unspeakable shadow must spend at least one of its actions each turn to either attack its shadow (making a Strike ineffectually) or flee from its shadow (using one action to move away as though it had the fleeing condition).\n\nCritical Success The target is unaffected.\n\nSuccess The target is Frightened 2.\n\nFailure The target is Frightened 3. It can't reduce its frightened value below 1 for 1 minute.\n\nCritical Failure The target is so afraid, it might instantly die. It must succeed at a Fortitude save or die; this saving throw has the incapacitation trait. If it succeeds at its save, the target is Frightened 4 and can't reduce its frightened value below 1 for 1 minute.","source":{"provider":"PAIZO","sourceId":"hq57j7Nif1zuQ2Ab","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.untwisting-iron-pillar","name":"Untwisting Iron Pillar","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","earth","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"5 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the earth and your ki to shield you from your enemies. You gain 50 temporary Hit Points that last for the duration or until you lose them, as well as resistance 5 to all physical damage (except adamantine).","source":{"provider":"PAIZO","sourceId":"9DtuMEyHhtHFRp5a","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.upheaval","name":"Upheaval","kind":"SPELL","rank":9,"rarity":"UNCOMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The ground in the area shudders and crumbles as huge pillars of stone erupt into the air, rending the terrain around them.\n\nThe GM might add additional effects in certain areas. Cliffs might collapse, causing creatures to fall, or a river might be blocked and flood the surrounding area.\n\n- Stone Debris The area becomes difficult terrain.\n\n- Rising Pillars Pillars of smooth stone rise from your chosen number of 10-foot squares on a surface in the area, ascending up to 60 feet in height. Each pillar stops when it hits a structure or ceiling unless that structure collapses (see below). The DC to Climb or Grab an Edge on a pillar is 30. Each creature on a pillar after it rises must succeed at a Reflex saving throw or fall off the nearest edge (the creature can choose which edge, if several are equally close). A creature on a pillar that is stopped by a structure falls without attempting a save.\n\n- Structural Collapse Structures and ceilings might collapse. The GM rolls a flat check for each (DC 14 for a sturdy structure, DC 9 for an average structure and most natural formations, all adjusted higher or lower as the GM sees fit). In general, shoddy structures automatically collapse. A collapse deals 11d6 bludgeoning damage to creatures beneath it; each creature caught in a collapse must attempt a Reflex save to avoid it. If the creature is forced to attempt a Reflex save because it was on a rising pillar, it uses the same result.\n\nCritical Success The creature takes half collapse damage.\n\nSuccess The creature takes half the collapse damage and falls .\n\nFailure The creature takes the full collapse damage and falls prone.\n\nCritical Failure The creature takes the full collapse damage and is by debris until it successfully Escapes (DC equal to the spell's save DC).","source":{"provider":"PAIZO","sourceId":"xxhS66k68u5iIOHC","book":"Pathfinder #156: The Apocalypse Prophet","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vital-singularity","name":"Vital Singularity","kind":"RITUAL","rank":9,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"crushed rubies worth 2,000 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion (legendary)","secondaryChecks":"Fortitude, Society, Will","secondaryCasters":3},"description":"When several companions or followers have reached a point of undying love and trust in you, they might be willing to die to save your life. You can grant them that wish. The secondary casters must be living creatures willing to sacrifice their energy to you, by allowing their life essence to drain out of them to protect you whenever you're in danger. If you're undead, the secondary casters must be undead instead, and if you're neither living nor undead, you can't cast vital singularity. Whenever you take damage, after calculating the total amount of damage, including immunities, resistances, weaknesses, and any other increases or mitigation, divide the amount by 4, rounding down. You and each of the secondary casters lose that many Hit Points. If a secondary caster doesn't have enough Hit Points to give before dropping to 0 Hit Points, you take any remaining damage for them as well. When a secondary caster reaches 0 Hit Points in this way, their skin dries out like leather as the last of their life leaves their bodies; this is a death effect.\n\nCritical Success The light from your secondary casters envelops you in a warm radiance. In addition to the effects described above, you're healed to full Hit Points upon completion of the ritual.\n\nSuccess The secondary casters channel their energies to you, protecting you as described above.\n\nFailure The secondary casters cry out in sorrow, reaching out to you to feel your embrace, then they grow sad that they couldn't live up to your expectations. Nothing else happens.\n\nCritical Failure The secondary casters' attempts to unite with you become desperate, but ultimately, the only function of the link was to disorient all of you, making your bodies feel like they aren't your own. You and all secondary casters become Clumsy 3 for 3 days.","source":{"provider":"PAIZO","sourceId":"KkimKrhDxEJVm6TH","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.void-harvest","name":"Void Harvest","kind":"RITUAL","rank":9,"rarity":"RARE","traits":["curse","mythic","void"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"TEXT","text":"1-mile radius circle centered on you"},"area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (mythic)","secondaryChecks":"Medicine (master), Occultism, Void Lore","secondaryCasters":3},"description":"The sky darkens over the affected area and the air becomes oppressive as you open a direct conduit to the Void, a plane of vast nothingness. Living creatures start to feel their life force draining away as the terror of oblivion begins to grip their hearts.\n\nEach year on the anniversary of the ritual's casting, a total of four casters can spend 1 hour at the center of the affected area to sustain the effect. To do so, one caster must spend 1 Mythic Point and succeed at a Religion check against the ritual's casting DC. Each year the ritual is successfully sustained, the radius increases from its original point by 1 mile. The effect fades away if the check fails or if there are no other attempts to sustain the ritual.\nCritical Success As success, but living creatures in the area take a –2 status penalty to saves against death effects or effects that deal void damage.\n\nSuccess The first time each day a living creature in the area takes damage, it must succeed at a Will save with a DC equal to the ritual's casting DC or gain the Doomed 1 condition; if it already has the doomed condition, it instead increases the value of it by 1. Dead creatures can't be raised or resurrected so long as their body remains in the ritual's area. Undead creatures gain vitality resistance equal to their level while in the area.\n\nFailure The ritual has no effect.\n\nCritical Failure An explosion of energy from the Void washes over the casters. Each caster becomes Drained 4. This condition can't be removed for 1 week.","source":{"provider":"PAIZO","sourceId":"NjK0kWRC6FYsPwXC","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.voracious-gestalt","name":"Voracious Gestalt","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["aura","concentrate","death","evil","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"14d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a powerful spirit entity that grows and builds strength by consuming the spirits of foes you both slay. When you Cast the Spell, the gestalt deals 14d6 void damage to all living creatures of your choice in the area, with a basic Fortitude save. Creatures you choose that end their turns in the area take (@item.level -3)d6[void] damage, with a basic Fortitude save.\n\nAt the end of each of your turns, if you killed a living creature during that turn or if the gestalt's damage killed a creature since the end of your prior turn, you add the slain creature's soul to the gestalt. The emanation's radius increases by 20 feet and the damage dealt by the aura increases by 1d6. (Note that this increase only happens once, even if you killed multiple living creatures that turn.) As normal for determining threat level, the GM determines if a creature is of significant enough threat to empower the gestalt; in general, a creature several levels below you rarely poses a significant threat.\nHeightened (10th) The initial damage increases to 16d6 and the aura's damage starts at 7d6 void damage.","source":{"provider":"PAIZO","sourceId":"drmvQJETA3WZzXyw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.wails-of-the-damned","name":"Wails of the Damned","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["auditory","concentrate","death","manipulate","void"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":40}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"8d10","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You howl a lament of damned souls. Each living enemy in the area takes 8d10 void damage and must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes full damage.\n\nFailure The creature takes full damage and is [[/r 1d4]].\n\nCritical Failure The creature takes double damage and is Drained 4.","source":{"provider":"PAIZO","sourceId":"FEsuyf203wTNE2et","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.weapon-of-judgment","name":"Weapon of Judgment","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You have a deity."},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"4d10","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"An immense weapon of spiritual energy appears, hovering in the air above the target. The weapon has the ghostly visual appearance of your deity's favored weapon. Name war or peace when you cast this spell.\n\nIf you name \"war,\" mentally choose one creature. This must be a creature both you and the target can see. The target instinctively knows which creature this is. At the end of each of the target's turns, if the target didn't use a hostile action against the creature you chose during that turn, the weapon Strikes the target.\n\nIf you name \"peace,\" mentally choose up to five allies. The target instinctively knows who those allies are. The weapon Strikes the target each time the target uses a hostile action against you or one of the chosen allies. The weapon Strikes only once per action, even if the action targets multiple allies (such as for a or a ).\n\nStrikes with the weapon are melee weapon attacks, but they use your spell attack modifier. Regardless of its appearance, the weapon deals 4d10 damage. The damage type is the same as the chosen weapon (or any of its types for a versatile weapon). The attack deals spirit damage instead if that would be more detrimental to the creature (as determined by the GM). No other statistics or attributes of the weapon apply, and even a ranged weapon attacks adjacent creatures only. The weapon takes a multiple attack penalty, which increases throughout the target's turn, but its penalty is separate from yours.\n\nA weapon of judgment is a weapon for the purposes of triggers, resistances, and so forth. The weapon doesn't take up space, grant flanking, or have any other attributes a creature would. The weapon can't make any attack other than its Strike, and feats or spells that affect weapons don't apply to this weapon.\nHeightened (10th) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"ZqmP9gijBmK7y8Xy","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.weird","name":"Weird","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["concentrate","death","emotion","fear","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"any number of creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"16d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fill the targets' minds with terrifying images of fearsome creatures, each drawn from the targets' worst fears. Only the targets can see their assailants. Each target takes 16d6 mental damage and must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and is Frightened 1.\n\nFailure The target takes full damage and is Frightened 2.\n\nCritical Failure The target is so afraid, it might instantly die. It must attempt a Fortitude saving throw. If the target succeeds, it takes double damage and is Frightened 2, and it's also until the end of its next turn unless it critically succeeded. If it fails, it is reduced to 0 Hit Points and dies.","source":{"provider":"PAIZO","sourceId":"qDjeG6dxT4aEEC6J","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wrathful-storm","name":"Wrathful Storm","kind":"SPELL","rank":9,"rarity":"COMMON","traits":["air","cold","concentrate","electricity","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":800},"area":{"shape":"BURST","feet":400}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A massive storm cloud forms in the air above the area, spreading rain and gales. The wind imposes a –4 circumstance penalty to physical ranged attacks. The air in the area is greater difficult terrain for flying creatures. When you Cast this Spell and the first time each round you Sustain it on subsequent rounds, you can choose one of the following storm effects. You can't choose the same effect twice in a row.\n- Blizzard The driving snow deals 4d8[cold] damage to each creature in or below the storm with no save. Everything in or beneath the cloud is by driving snow and any ground is difficult terrain.\n- Hail Each creature in or below the storm takes 4d10[bludgeoning] damage with a basic Fortitude save.\n- Lightning Choose up to 10 creatures in or below the storm to be struck by lightning. Each of them takes 7d6[electricity] damage with a basic Reflex save.\n- Tornado A roughly cylindrical whirlwind appears in or below the cloud in a 30-foot radius. Each creature in the whirlwind is thrown 40 feet upward.\n\nHeightened (10th) The range increases to 2,000 feet and the cloud is a 1,000-foot burst.","source":{"provider":"PAIZO","sourceId":"yLJROsQtyrPIKcDx","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.alter-reality","name":"Alter Reality","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You use your occult lore and the power of your mind to manipulate the spiritual multiverse, resulting in any of the following effects:\n\n- Duplicate any occult spell of 9th rank or lower to which you have access.\n\n- Duplicate any spell from another spell list of 7th rank or lower. It must be common or you must have access.\n\n- Produce any effect whose power is in line with the above.\n\n- Reverse certain effects that refer to the spell.\n\nAt the GM's discretion, you can try to produce greater effects, but this is dangerous and the spell may have only a partial effect.","source":{"provider":"PAIZO","sourceId":"h8zxY9hTeHtWsBVW","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.anima-invocation-modified","name":"Anima Invocation (Modified)","kind":"RITUAL","rank":10,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"TEXT","text":"10 miles"},"target":"Primary and Secondary Casters","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (Legendary)","secondaryChecks":"Arcana, Religion","secondaryCasters":4},"description":"When casting the modified version of the Anima Invocation, it instead draws upon the latent spiritual energies of sapient creatures within range of the spell without requiring their deaths, then uses this energy to bolster the connection between body and soul among all of the ritual's casters. This shift from an offensive effect to a defensive one results in a much less dangerous spell that helps to protect against Dahak.\n\nCritical Success You gain full access to your own potential for 1 day. You gain resistance 10 to all damage and a +4 status bonus to saves against effects created by evil creatures. Your Strikes gain the effects of the rune and deal an additional 1d10 spirit damage. You are immune to the soul-draining effect within Alseta's Landing.\n\nSuccess You tap into your own potential for 1 day. You gain resistance 5 to all damage and a +2 status bonus to saves against effects created by evil creatures. Your Strikes gain the effects of the ghost touch rune and deal an additional 1 spirit damage. You are immune to the soul-draining effect within Alseta's Landing.\n\nFailure You are unable to tap into your own spiritual essence, but you still gain immunity to the soul-draining effect within Alseta's Landing.\n\nCritical Failure You botch the ritual, damaging your own spiritual essence. You gain Doomed 1 or increase your doomed condition by 1 if you're already doomed. This doomed value decreases by 1 every week. This is a curse effect.","source":{"provider":"PAIZO","sourceId":"X0t0gr7S7CeCt2Q5","book":"Pathfinder #150: Broken Promises","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.apex-companion","name":"Apex Companion","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","manipulate","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 animal companion in your service","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus on the energies of all members of your animal companion's species, transforming your animal companion into its apex battle form. Your animal companion gains the following statistics and abilities while in its apex form.\n\n- Your animal companion becomes Huge and its attacks have 15-foot reach. It must have enough space to expand into or the spell is lost.\n\n- 30 temporary Hit Points.\n\n- Darkvision.\n\n- Your animal companion's attack's damage dice increase by one step, and its attack gains the deadly d12 trait.\n\n- +10-foot status bonus to its Speeds.\n\n- Ignores difficult terrain and greater difficult terrain.","source":{"provider":"PAIZO","sourceId":"qqQYrXaRJXr7uc4i","book":"Pathfinder #150: Broken Promises","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.avatar","name":"Avatar","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform into an avatar of your deity, assuming a Huge battle form. You have hands in this battle form and can take manipulate actions. You can Dismiss this spell. You gain the following statistics and abilities regardless of which deity's battle form you assume:\n\n- AC = 25 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 30 temporary Hit Points.\n\n- Darkvision.\n\n- One or more attacks specific to your deity's battle form, which are the only attacks you can with. You're trained with them. Your attack modifier is +33, and you use the listed damage. Melee attacks are Strength based (for the purposes of the condition, for example) unless they have the finesse trait, and all ranged attacks are Dexterity based.\n\n- Athletics modifier of +35, unless your own is higher.\n\nYou also gain the specific abilities listed for your deity below:\n\n- Abadar\n\n- Speed 50 feet, burrow Speed 30 feet, immune to ;\n\n- Ranged a crossbow (range increment 120 feet, reload 1), Damage 6d10+3 piercing.\n\n- Achaekek\n\n- Speed 70 feet, climb Speed 50 feet, ignore difficult terrain and greater difficult terrain;\n\n- Melee a mantis claw (agile, backswing, finesse, reach 15 feet, versatile P), Damage 6d8+6 slashing;\n\n- Ranged a spine volley (range 60 feet), Damage 6d6+3 piercing\n\n- Asmodeus\n\n- Speed 70 feet, fly;\n\n- Melee a mace (reach 15 feet), Damage 6d10+6 bludgeoning;\n\n- Ranged a hell fire (range 120 feet), Damage 6d6+3 fire.\n\n- Calistria\n\n- Speed 30 feet, fly Speed 70 feet;\n\n- Melee a whip (disarm, finesse, nonlethal, reach 20 feet), Damage 6d4+6 slashing;\n\n- Ranged a savored sting (range 60 feet), Damage 6d6+3 poison.\n\n- Cayden Cailean\n\n- Speed 70 feet, fly, ignore difficult terrain and greater difficult terrain;\n\n- Melee a rapier (deadly 3d8, reach 15 feet), Damage 6d6+6 piercing;\n\n- Ranged a ale splash (range 120 feet), Damage 6d6+3 poison.\n\n- Desna\n\n- Speed 30 feet, fly Speed 70 feet;\n\n- Melee a starknife (agile, deadly 3d4, finesse, reach 15 feet, silver, thrown 60 feet), Damage 6d4+6 piercing;\n\n- Ranged a moonbeam (range 120 feet, silver), Damage 6d6+3 fire.\n\n- Erastil\n\n- Speed 70 feet, fly, ignore difficult terrain and greater difficult terrain;\n\n- Ranged a longbow (deadly 3d8, range increment 150 feet), Damage 6d8+3 piercing.\n\n- Gorum\n\n- Speed 70 feet, immune to ;\n\n- Melee a greatsword (versatile P, reach 15 feet), Damage 6d12+6 slashing.\n\n- Gozreh\n\n- no land Speed, fly Speed 70 feet, swim Speed 70 feet, ignore difficult terrain and greater difficult terrain;\n\n- Melee a waves (reach 15 feet, shove, thrown 20 feet), Damage 6d8+6 bludgeoning;\n\n- Ranged a wind (versatile electricity, range 120 feet), Damage 6d6+3 bludgeoning.\n\n- Iomedae\n\n- Speed 70 feet, fly; shield (15 Hardness, can't be damaged);\n\n- Melee a longsword (versatile P, reach 15 feet), Damage 6d8+6 slashing.\n\n- Irori\n\n- Speed 80 feet, fly;\n\n- Melee a unfettered strike (agile, versatile P or S, finesse, reach 15 feet), Damage 6d8+6 bludgeoning;\n\n- Ranged a wind strike (range 60 feet), Damage 6d4+6 bludgeoning.\n\n- Lamashtu\n\n- Speed 30 feet, fly Speed 70 feet;\n\n- Melee a falchion (forceful, reach 15 feet), Damage 6d10+6 slashing;\n\n- Ranged a waters of Lamashtu (range 120 feet), Damage 6d6+3 poison.\n\n- Nethys\n\n- Speed 70 feet, fly;\n\n- Ranged a raw magic (range 120 feet; versatile cold, electricity, or fire), Damage 6d6 force.\n\n- Norgorber\n\n- Speed 70 feet, fly, ignore difficult terrain and greater difficult terrain;\n\n- Melee a shortsword (agile, finesse, versatile S, reach 15 feet), Damage 6d6+6 piercing;\n\n- Ranged a blackfinger toss (range 120 feet), Damage 6d6+3 poison.\n\n- Pharasma\n\n- Speed 70 feet, fly;\n\n- Melee a dagger (agile, finesse, reach 15 feet, thrown 40 feet), Damage 6d6+6 slashing;\n\n- Ranged a spiral blast (range 120 feet, damages only undead), Damage 6d8+3 vitality.\n\n- Rovagug\n\n- Speed 50 feet, burrow Speed 30 feet, immune to ;\n\n- Melee a jaws (reach 15 feet), Damage 6d12+6 piercing;\n\n- Melee a leg (agile, versatile P, reach 15 feet), Damage 6d8+6 bludgeoning.\n\n- Sarenrae\n\n- Speed 30 feet, fly Speed 70 feet;\n\n- Melee a scimitar (forceful, nonlethal, reach 15 feet), Damage 6d6+6 slashing;\n\n- Ranged a everflame (nonlethal, range 120 feet), Damage 6d6+3 fire.\n\n- Shelyn\n\n- Speed 70 feet, fly, ignore difficult terrain and greater difficult terrain;\n\n- Melee a glaive (deadly 3d8, nonlethal, reach 20 feet), Damage 6d8+6 slashing;\n\n- Ranged a melody of inner beauty, (nonlethal, range 120 feet), Damage 6d6+3 sonic.\n\n- Torag\n\n- Speed 50 feet, burrow Speed 30 feet, immune to ; shield (15 Hardness, can't be damaged);\n\n- Melee a warhammer (reach 15 feet, shove), Damage 6d8+6 bludgeoning.\n\n- Urgathoa\n\n- Speed 70 feet, fly;\n\n- Melee a scythe (deadly 3d10, trip, reach 15 feet), Damage 6d10+6 slashing;\n\n- Ranged a pallid plague (range 120 feet), Damage 6d6+3 void.\n\n- Zon-Kuthon\n\n- Speed 70 feet, fly, ignore difficult terrain and greater difficult terrain;\n\n- Melee a spiked chain (disarm, trip, reach 15 feet), Damage 6d8+6 slashing;\n\n- Ranged a midnight pain (mental, nonlethal, range 120 feet), Damage 6d6+3 mental.","source":{"provider":"PAIZO","sourceId":"ckUOoqOM7Kg7VqxB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cataclysm","name":"Cataclysm","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["acid","air","cold","concentrate","earth","electricity","fire","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"1,000 feet"},"area":{"shape":"BURST","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d10","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"2","formula":"3d10","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false},{"id":"3","formula":"3d10","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false},{"id":"4","formula":"3d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"5","formula":"3d10","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the unimaginable power of world-ending cataclysms, ripping a small piece of each cataclysm and combining them together into one horrifically powerful attack. The following effects come down upon all creatures in the area. Treat the resistances of creatures in the area as if they were 10 lower for the purpose of determining the cataclysm's damage. Each creature attempts one basic Reflex save that applies to all five types of damage.\n\n- Flesh-dissolving acid rain deals 3d10 acid damage.\n\n- A roaring earthquake shakes and bludgeons creatures on the ground, dealing 3d10 bludgeoning damage.\n\n- A blast of freezing wind deals 3d10 cold damage.\n\n- Incredible lightning lashes the area, dealing 3d10 electricity damage.\n\n- Beating winds churn across the sky, dealing 3d10 bludgeoning damage to creatures flying in the area.\n\n- An instant tsunami sweeps over creatures in the area, dealing 3d10 bludgeoning damage with the water trait (doubled for creatures swimming in the area).\n\n- A massive wildfire burns in a sudden inferno, dealing 3d10 fire damage.","source":{"provider":"PAIZO","sourceId":"wLIvH0AT1u7oa64N","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.conquering-soldiers","name":"Conquering Soldiers","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tap into the glories of the armies of old, bringing forth their might to your battlefield and making their strength and power your own. This army manifests as glimmering forms of a conquering military of old, replete with banners and colors of their nation. The army occupies the space of a Gargantuan creature and has a Speed of 80 feet.\n\nArrive (auditory, emotion, fear, mental) Banner's Call The conquering army manifests before you and your allies, letting out a battle cry of victory and devotion. Each enemy within an 80-foot emanation must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature is Frightened 2.\n\nFailure The creature takes 6d12 mental damage and is Frightened 3.\n\nCritical Failure The creature takes 12d12[mental|options:area-damage|traits:auditory,emotion,fear,mental] damage, is Frightened 4, and is for 1 round.\n\nDepart (emotion, healing, mental) Trumpets of War As the conquering soldiers begin to fade, their military musicians play one more triumphant song in your honor. You and all allies within 100 feet of the soldiers immediately reduce the value of any , , , , , and conditions by 2 and gain a +2 status bonus to all attacks, saving throws, skill checks, and DCs for 3 rounds.","source":{"provider":"PAIZO","sourceId":"ion3VOiLan6ga3QC","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.destroy-mindscape","name":"Destroy Mindscape","kind":"RITUAL","rank":10,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"the mindscape's anchors"},"targeting":{"range":{"kind":"NONE"},"target":"the mindscape","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (legendary)","secondaryChecks":"Arcana or Occultism, Crafting","secondaryCasters":2},"description":"After you gather the anchors that make up the mindscape's structure, or in the case of anchors too immense to move, when you gain control over the region surrounding the anchors, you can perform this ritual to tear the mindscape apart from within. The ritual takes but a day to attempt, so those who would oppose such a destructive doom would do well to challenge the enemy by doing what they can to protect their mindscape's anchors. At the GM's discretion, the most powerful of mindscapes, such as those created by a deity, might be immune to this ritual's effects.\n\nOver the course of this ritual's casting, you and the secondary casters unravel the basic and fundamental ideas of the mindscape's anchors. As you do so, flashes of memory tied to the anchor you target flood your mind, before the anchor itself dissipates. The mindscape might react with hostility to this process, manifesting creatures or swaying primary inhabitants to stop you. Regardless of how many anchors in all must be dismantled, it always takes a day to perform this ritual.\n\nCritical Success The mindscape is destroyed, and you and the secondary casters are returned to the plane from which you hailed before entering the mindscape.\n\nSuccess The mindscape is destroyed, but you and the secondary casters are scattered randomly to locations on other planes.\n\nFailure The mindscape is not destroyed, and you and the and the secondary casters are scattered randomly to locations on other planes.\n\nCritical Failure The mindscape is not destroyed, and you and the secondary casters become Drained 3 and are then each plunged into separate mindscapes. You remain trapped therein until you engineer each of your own escapes. You forget the destroy mindscape ritual and must discover it again if you wish to pursue this goal once more.","source":{"provider":"PAIZO","sourceId":"dQGn0eAyvYMDdj0h","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dinosaur-fort","name":"Dinosaur Fort","kind":"SPELL","rank":10,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"24 hours (see text)","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a primeval fort with walls of sharpened wood adorned with dinosaur skin and teeth, up to 300 feet on a side. Each of the four quadrants of the fort is guarded by a . While the tyrannosauruses won't cross into the others' territories, their reach allows them to simultaneously attack an intruder near the center of the fort. The tyrannosauruses leave you and anyone you introduce to them alone but treat anyone else they find in the fort as intruders and prospective snacks. When you prepare spells, you can choose not to recover the spell slot you used to cast this spell. If you do, the fort remains for another 24 hours.\n\nThe fort must be created on a plot of land free of other structures. It adapts to the natural terrain, adopting the structural requirements for being built there. The fort adjusts around small features, such as ponds or spires of rock, but can't be created on water or other nonsolid surfaces. If created on snow, sand dunes, or other soft surfaces with a solid surface underneath, the foundation reaches solid ground. If created on a solid but unstable surface, such as a swamp or an area plagued by tremors, roll a flat each day the fort is present; on a failure, the fort sinks or collapses sometime during that day, and the spell ends.\n\nThe fort doesn't harm creatures within the area when it appears, and it can't be created within a crowd or in a densely populated area. Any creature inadvertently caught inside the fort when the spell is cast ends up unharmed inside the complete fort and always has a clear path of escape.","source":{"provider":"PAIZO","sourceId":"FA55Fxf8MBXhje95","book":"Pathfinder #177: Burning Tundra","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dragon-turret","name":"Dragon Turret","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"CYLINDER","feet":10}},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"EOjlR2U7ZKBcz8lK","formula":"13d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area (continued) an empty 10-foot radius, 50-foot-tall cylinder\nYou conjure forth a massive tower with a large dragon that's bound to crawl its length. The dragon and the tower share the same space, and the dragon intercepts any attack targeting the tower. When the dragon dies, the tower crumbles. The dragon is immune to all conditions, has an AC of 40, a +30 modifier for all saving throws, and 250 Hit Points. When you Cast the Spell, and once per round when you Sustain it, the dragon unleashes its breath in a , dealing 13d8 damage (basic Reflex save). The damage type depends on the tradition used to cast this spell: arcane force, divine spirit, occult mental, primal fire.","source":{"provider":"PAIZO","sourceId":"eAOClJ1KRSPik8SX","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.element-embodied","name":"Element Embodied","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Drawing upon the deepest wells of magic in an elemental plane, you transform into a spectacular elemental. You can choose between an air elemental, earth elemental, fire elemental, or water elemental. Your battle form is Gargantuan, and you must have enough space to expand into or the spell is lost. While in this form, you gain the elemental trait and the trait for the element you choose. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 25 + your level. Ignore your armor's check penalty and Speed reduction.\n- 30 temporary Hit Points.\n- Darkvision.\n- One or more attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +34, and you use the listed damage. These attacks are Dexterity based if you choose an air or fire elemental, or Strength based if you choose an earth or water elemental. (This distinction doesn't change the statistics, but matters for the enfeebled and clumsy conditions, for example). If your unarmed attack modifier is higher, you can use it instead.\n- Acrobatics modifier of +36 for air or fire elemental or Athletics modifier of +36 for earth or water elemental, unless your own modifier is higher.\nYou also gain specific abilities based on the type of elemental you choose:\n- Air Elemental fly Speed 80 feet;\n- High Winds (air, aura) 30 feet. Air within the emanation is difficult terrain for flying creatures that don't have the air trait;\n- Swiftness Your movement doesn't trigger reactions;\n- Melee 1 gust (reach 25 feet), Damage 3d12+11 bludgeoning plus Push 10 feet;\n- Ranged 1 lightning lash (range increment 80 feet), Damage 3d12+4 electricity.\n\n- Earth Elemental 30 feet, burrow 20 feet; resistance 5 to physical;\n- Spike Stones (aura, earth) 30 feet. The area is difficult terrain and hazardous terrain. A creature without the earth trait that moves on the ground in the area takes 5 piercing damage for every square of that area it moves into;\n- Rocky Toughness You gain 40 temporary Hit Points when you choose this form instead of 30;\n- Melee 1 fist (reach 25 feet), Damage 3d12+15 bludgeoning;\n- Ranged 1 rock (range increment 40 feet), Damage 4d8+6 bludgeoning.\n\n- Fire Elemental 50 feet; immunity to fire; weakness to cold 10;\n- Intense Heat (aura, fire) 30 feet. A creature that enters the aura or starts its turn in the aura takes 5d6 fire damage with a basic Reflex save against your spell DC. A creature can take damage from the aura only once per round;\n- Melee 1 tendril (reach 25 feet), Damage 3d10+12 fire plus 2d6 persistent fire;\n- Ranged 1 fire mote (range increment 60 feet), Damage 4d8+6 fire.\n\n- Metal Elemental 40 feet, fly 40 feet; resistance 10 to electricity;\n- Arcing Electricity (aura, electricity, metal) 30 feet. A creature that enters the aura or starts its turn in the aura takes 2d12[electricity] damage with a basic Reflex save against your spell DC; a creature made of metal, with the metal trait, or wearing metal armor takes a –1 circumstance penalty on this save. A creature can take damage from the aura only once per round;\n- Melee 1 blade (reach 25 feet, versatile slashing), Damage 3d12+15 piercing;\n- Ranged 1 metal shard (range increment 40 feet, versatile slashing), Damage 4d8+6 piercing.\n\n- Water Elemental 40 feet, swim 80 feet; resistance 10 to fire;\n- Vortex (aura, water) 30 feet. Water within the aura that is part of the same body of water you occupy is difficult terrain for Swimming creatures that don't have the water trait;\n- Melee 1 wave (reach 25 feet), Damage 3d12+18 bludgeoning plus Push or Pull 10 feet;\n- Ranged 1 water spout (range increment 60 feet), Damage 4d8+6 bludgeoning.\n\n- Wood Elemental 30 feet, climb 35 feet; resistance 5 to physical; weakness to axes 10;\n- Lush Growth (aura, wood) 30 feet. Ground in the area is difficult terrain, and any time a creature in the area regains HP from a healing vitality effect, the aura grants a +5 status bonus to the healing;\n- Woody Toughness You gain 40 temporary Hit Points when you choose this form instead of 30;\n- Melee 1 branch (reach 25 feet), Damage 3d10+18 piercing;\n- Ranged 1 seed (range increment 40 feet), Damage 4d8+6 bludgeoning.","source":{"provider":"PAIZO","sourceId":"vQMAdnIwnV9prPiG","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fabricated-truth","name":"Fabricated Truth","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"up to 5 creatures","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Choose a single statement you want the targets to believe. The fact could be narrow, such as \"a dragon is circling overhead and wants to kill me\"; wide-reaching, such as \"all humanoids are disguised abominations\"; or conceptual, such as \"if I don't live a kinder life, I'll be punished in the afterlife.\" The targets' experiences color how they react to this \"truth\" and how their behavior changes. If the statement changes what they perceive, they treat the change as a sudden revelation. The effect of the spell depends on the targets' Will saves. If a target is already affected by fabricated truth, your spell tries to counteract it. If the counteract check fails, the outcome of the target's saving throw can't be worse than a success.\n\nCritical Success The target doesn't believe the statement, and it knows you tried to trick it.\n\nSuccess The target doesn't believe the statement or realize you tried to trick it.\n\nFailure The target believes the statement for 1 week.\n\nCritical Failure The target believes the statement with unlimited duration.","source":{"provider":"PAIZO","sourceId":"6s0UW4bujggma9TC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fatal-aria","name":"Fatal Aria","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","death","emotion","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You perform music so perfect that the target may die of joy or sorrow. Once targeted, the creature becomes temporarily immune for 1 minute. The effect of the spell depends on the target's level and current Hit Points.\n\n16th or Lower The target dies instantly.\n\n17th If the target has 50 Hit Points or fewer, it dies instantly; otherwise, it drops to 0 Hit Points and becomes Dying 1.\n\n18th or Higher The target takes 50[untyped] damage. If this brings it to 0 Hit Points, it dies instantly.","source":{"provider":"PAIZO","sourceId":"lyJDBD9OFW11vLyT","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fated-confrontation","name":"Fated Confrontation","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"120"},"target":"1 willing ally and 1 enemy","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You weave the threads of fate to lead two foes into a climactic battle. The targets of this spell are the fated opponents: one of the targets of this spell must be you or a willing ally, and the other must be an enemy.\n\nWhen you Cast the Spell, the ally you targeted (or you, if you targeted yourself) may teleport to any unoccupied space of their choice within 30 feet of its fated opponent. This is a teleportation effect.\n\nYou isolate the two targets for 1 round. During this time, fate refuses to allow either fated opponent to be affected by attacks or effects from a third party; a fated opponent could be affected by the other's meteor swarm or its own heal spell, but it would be entirely immune to a spell or Strike from a creature outside of the spells effects, as well including damage from a hazard or the environment. This doesn't apply to anything that was affecting the targets before you cast fated confrontation (such as a spell with a duration or persistent damage the creature had before it was affected by fated confrontation). For the duration of the spell, either fated opponent can manipulate fate once on each of its turns. This allows it to either roll twice and take the higher result on an attack roll or skill check it makes against its fated opponent (a fortune effect), or force the fated opponent to roll twice on a saving throw against one of its abilities and take the lower result (a misfortune effect).\n\nThis spell ends if either target becomes unable to act, or if they both agree to cease hostilities.","source":{"provider":"PAIZO","sourceId":"Di9gL6KIZ9eFgbs1","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.freeze-time","name":"Freeze Time","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You temporarily stop time for everything but yourself, allowing you to use several actions in what appears to others to be no time at all. Immediately after casting freeze time, you can use up to 9 actions in 3 sets of up to 3 actions each.\n\nAfter each set of actions, 1 round passes, but for only you, effects specifically targeting or affecting you, and effects that you create during the stoppage. All other creatures and objects are invulnerable to your attacks, and you can't target or affect them with anything.\n\nOnce you have finished your actions, time begins to flow again for the rest of the world. If you created an effect with a duration that extends beyond freeze time's duration, such as , it immediately affects others again, but it doesn't have any of the effects that happen only when you first Cast the Spell.","source":{"provider":"PAIZO","sourceId":"1dsahW4g1ggXtypx","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.garden-of-the-green-mans-growth","name":"Garden of the Green Man's Growth","kind":"SPELL","rank":10,"rarity":"RARE","traits":["concentrate","incarnate","manipulate","mythic"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cast your magic into the earth, calling out to a powerful green man, a verdant lesser deity of nature, to come to your aid. They occupy the space of a Medium creature, have a Speed of 40 feet, and a climb Speed of 40 feet.\n\nArrive (plant) Verdant Bloom The green man erupts from the ground in a burst of lush growth, dealing 10d8[bludgeoning] damage to creatures in a with a basic Reflex save. Creatures that fail this save are pushed 30 feet away from the green man and are knocked . The area becomes greater difficult terrain for 24 hours.\n\nDepart (plant) Forest of Grasping Vines The green man casts out their arms, causing vines to rise from the ground, lash at up to six different creatures, and coil them up. Each of these vines targets a different enemy within 100 feet of the green man and deals 12d6[slashing] damage with a basic Reflex save. A creature that fails is until it Escapes (on a critical failure it is until it Escapes). The DC is your spell DC. Each creature that begins its turn grabbed or by these vines takes an additional 4d6[bludgeoning] damage, as the vines continue to squeeze the life from it.","source":{"provider":"PAIZO","sourceId":"jQgX7zChqjFrU7Q1","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gate","name":"Gate","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tear open a rift to another plane, creating a portal that creatures can travel through in either direction. This portal is vertical and circular, with a radius of 40 feet. The portal appears at a location of your choice on the destination plane, assuming you have a clear idea of both the destination's location on the plane and what the destination looks like. If you attempt to create a gate into or out of the realm of a deity or another similarly powerful being, that being can prevent the gate from forming.","source":{"provider":"PAIZO","sourceId":"U13bC0tNgrlHoeTK","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.halt-death","name":"Halt Death","kind":"RITUAL","rank":10,"rarity":"RARE","traits":["vitality"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"},"cost":"an hourglass filled with ebon sand, worth at least 10,000 gp"},"targeting":{"range":{"kind":"NONE"},"target":"all living creatures","area":{"shape":"EMANATION","feet":5280}},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Warfare Lore (legendary)","secondaryChecks":"Medicine, Occultism, Pharasma Lore","secondaryCasters":3},"description":"While death may be war's stock and trade, you attempt to momentarily delay the inevitable. Upon the successful completion of the ritual, the sands of the hourglass begin to slowly float upward into the upper bulb over the course of the next 24 hours. The hourglass shatters at the end of the ritual's duration, ending the protective magic.\nCritical Success All living creatures within the area are guarded against death, gaining a +4 status bonus to saving throws against death effects. In addition, when a living creature in the area succeeds at a recovery check, they get a critical success instead. Finally, the first time during the duration that a living creature would be reduced to dying 2 or higher, that creature remains at dying 1 instead.\n\nSuccess All living creatures within the area are guarded against death, gaining a +2 status bonus to saving throws against death effects. In addition, the first time during the duration that a living creature would be reduced to dying 3 or higher, that creature remains at dying 2 instead.\n\nFailure The ritual has no effect.\n\nCritical Failure Attempting to stave off death earns Pharasma's ire. You and all the secondary casters become Doomed 2. This condition can't be reduced or removed for 1 week.","source":{"provider":"PAIZO","sourceId":"NQk8Cabhhw7jXkg0","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heros-defiance","name":"Hero's Defiance","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["champion","concentrate","focus","healing","vitality"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"6d8+20","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An attack would bring you to 0 Hit Points.\nYou shout in defiance and are filled with a burst of healing. Just before applying the attack's damage, you recover 6d8+20 Hit Points. If this is enough to prevent the attack from bringing you to 0 Hit Points, you don't become or . Either way, cheating death is difficult, and you can't use hero's defiance again until you Refocus or make your daily preparations. Hero's defiance can't be used against effects with the death trait or that would leave no remains, such as disintegrate.","source":{"provider":"PAIZO","sourceId":"uGXWkR2h8q9MRzEM","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.indestructibility","name":"Indestructibility","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sever yourself from cause and effect. For the duration of the spell, you are immune to any effect or damage that would harm you, excluding effects caused by artifacts, deific power, and similarly powerful sources. You can selectively allow yourself to be affected by anything you're willing to have affect you.","source":{"provider":"PAIZO","sourceId":"UG0SmRYSdbrx2rTA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.jassims-allegiance","name":"Jassim's Allegiance","kind":"SPELL","rank":10,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bartered for this spell in some strange market or perhaps gained it while wandering the desert, hopelessly lost and surrounded by nothing but the remnants of time and fallen empires. With a gesture and words of a language not spoken since the fall of the Hanging City of Teskra, you summon Jassim the Wanderer. Jassim, a true Jistkan automaton, occupies the space of a Gargantuan creature and has a Speed of 60 feet.\n\nArrive (fire) Eyes of Fire Jassim emerges from the ground and glares at your enemies, a fearsome look forming on a face of ancient metal and glass. He shoots an energy beam in a 60-foot line, dealing 5d12 fire damage and 5d12 piercing damage (basic Reflex save). Enemies that critically fail are Drained 2.\n\nDepart (metal) Heart of Rust Jassim takes a metal piece from his chest and holds it out, crushing it in his fist and allowing the powder to spread across a 60-foot emanation. These particles deal 10d6 slashing damage to all creatures and unattended objects within the area (basic Fortitude save). A metal creature that fails its save also takes 2d8[persistent,slashing|traits:metal] damage. A non-metal creature that fails this save is also Sickened 2.","source":{"provider":"PAIZO","sourceId":"JEMSVySuS4jvTepQ","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.manifestation","name":"Manifestation","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You spin secrets from the fundaments of magic, shaping them into a power with nearly unlimited potential. You duplicate a spell of 9th rank or lower of the tradition from which you cast manifestation, or a spell of 7th rank or lower from any tradition. Though you can normally choose only spells that are common or to which you have access, the GM might allow broader options.","source":{"provider":"PAIZO","sourceId":"AuIiqc7jjiy1GZ75","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.miracle","name":"Miracle","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You request aid directly from your divine source. Your divine source always refuses a request out of line with its nature, and it might grant a different request (potentially more powerful or better fitting its nature) than the one you asked for. A casting of miracle can do any of the following things.\n\n- Duplicate any spell from the divine list of 9th rank or lower to which you have access.\n\n- Duplicate any spell from another spell list of 7th rank or lower. It must be common or you must have access.\n\n- Produce any effect whose power level is in line with the above effects.\n\n- Reverse certain effects that refer to the spell.\n\nThe GM might allow you to try using miracle to produce greater effects than these, but doing so may be dangerous, or the spell may have only a partial effect.","source":{"provider":"PAIZO","sourceId":"YfJTXyVGzLhM6V8U","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nature-incarnate","name":"Nature Incarnate","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The primal power of the world flows through you. You transform into an incarnation of nature, either a green man or a kaiju. Your battle form is Medium for a green man or Gargantuan (30-foot-by-30-foot space) for a kaiju. While in this form, you gain the plant trait (for a green man) or the beast trait (for a kaiju). You can Dismiss the spell. You gain the following statistics and abilities regardless of which battle form you choose:\n\n- AC = 25 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 30 temporary Hit Points.\n\n- Darkvision.\n\n- One or more attacks specific to the battle form you choose, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +34, and you use the listed damage. These attacks are Strength based (for the purpose of the condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n\n- Athletics modifier of +36, unless your own is higher.\n\nYou gain specific abilities based on the incarnation you choose:\n\n- Green Man\n\n- Speed 40 feet, climb 40 feet;\n\n- Melee 1 vines (reach 30 feet, versatile P), Damage 6d8+12 bludgeoning;\n\n- Ranged 1 thorns (range 100 feet), Damage 6d6+6 piercing;\n\n- Green Caress (aura, primal) 60 feet. Enemies other than plants must succeed at a fortitude against your spell DC or become Clumsy 1 for 1 round (Clumsy 2 on a critical failure).\n\n- Kaiju\n\n- Speed 50 feet; resistance 5 to physical damage;\n\n- Melee 1 jaws (reach 30 feet), Damage 6d10+10 piercing;\n\n- Melee 1 claws (agile, reach 30 feet), Damage 6d8+8 slashing;\n\n- Melee 1 foot (agile, reach 15 feet), Damage 6d6+10 bludgeoning;\n\n- Unstoppable You are immune to being and ignore difficult terrain and greater difficult terrain;\n\n- Trample 3 You move up to double your Speed and move through the spaces of Huge or smaller creatures, trampling each creature whose space you enter. A trampled creature takes foot damage with a reflex save against your spell DC.","source":{"provider":"PAIZO","sourceId":"ZXwxs5tRjEGrjAJT","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nullify","name":"Nullify","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"the triggering spell","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A foe within range casts a 9th-rank or lower spell.\n\nYou instantly destroy the incoming spell, though at the cost of sending magical feedback through your body. You automatically counteract the spell, but the feedback brings you unavoidable harm. You lose 1d8 Hit Points per rank of the triggering spell.","source":{"provider":"PAIZO","sourceId":"KRcccPeNZOZ5Nweh","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.perfection-of-essence","name":"Perfection of Essence","kind":"RITUAL","rank":10,"rarity":"RARE","traits":["trial"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"special foods, herbs, and minerals worth a total value of 45,000 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (expert)","secondaryChecks":"Medicine, Religion","secondaryCasters":1},"description":"Many have pursued alchemical means to immortality, and most haven't survived the attempt. The most common manner of purifying one's essence requires ingesting the following poison, and surviving the effects unassisted for at least a day.\n\nSaving Throw fortitude\n\nOnset 1 hour\n\nMaximum Duration 5 days\n\nStage 1 7d12[spirit] damage plus Doomed 1 (1 hour)\n\nStage 2 9d12[spirit] damage and for 1 minute once every [[/gmr 1d4 #minutes]]{1d4 minutes}, plus Doomed 2 (1 hour)\n\nStage 3 9d12[spirit] damage and Doomed 3 (1 day)\n\nStage 4 death\n\nAnathema for this ritual is determined at the time of the ritual. You choose 1 anathema, and the GM chooses 2 anathema. You're aware of all of your anathema. Appropriate anathema might include avoiding physical contact with a certain creature or substance (such as members of your bloodline or jade), eating certain foods (such as meat or grains), or wearing certain items or materials (such as silk or cotton). If the ritual is ended in this way, you must conduct an ritual before attempting this ritual again.\n\nCritical Success As success, except you choose 1 anathema and your GM chooses 1 anathema.\n\nSuccess You've purified your body enough to attempt to attain immortality. You're bound by the ritual's anathema and must ingest the final potion to complete your apotheosis. Once you've withstood the effects of the poison for 1 day or completely recovered from the poison's effects without outside assistance, you gain immortality as follows: you don't age unless you wish to. You can't die except due to old age; if your dying or doomed condition would increase to a high enough value to kill you, it doesn't increase, and any effect that would instantly kill you instead just reduces you to 0 Hit Points. If you ever truly die and aren't returned to life within 1 year, you descend from the Heavens as an adult into a new mortal body somewhere in the world.\n\nFailure Your actions don't achieve immortality, and you automatically fail the first save against the poison.\n\nCritical Failure As failure, except the poison is also virulent.","source":{"provider":"PAIZO","sourceId":"kExRMPVI07iIFCaa","book":"Pathfinder Lost Omens Tian Xia World Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pied-piping","name":"Pied Piping","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus","incapacitation","mental","sonic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your performance enraptures listeners, compelling them to follow you. Each creature within the emanation must attempt a Will save when you Cast the Spell or the first time they enter the area, after which they become temporarily immune for 1 day. Once per turn, you can Sustain the composition to increase the emanation's radius by 5 feet. You can Dismiss the spell.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is with you.\n\nFailure The creature is fascinated by you and uses all its actions to move toward you and compliment your performance. This effect ends if a hostile action is used against the affected creature.\n\nCritical Failure The target gains the minion trait and is controlled by you. This effect ends if a hostile action is used against the affected creature, or if you direct the creature to use any action that causes it harm.","source":{"provider":"PAIZO","sourceId":"Um0aaJotqMKGmAlR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.primal-herd","name":"Primal Herd","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you and up to 5 willing targets","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Summoning the power of the natural world, you transform the targets into a herd of mammoths, and they each assume a Huge battle form. Each target must have enough space to expand into or the spell fails for that target. Each target gains the animal trait. Each target can Dismiss the spell's effects on itself. Each target gains the following while transformed.\n- AC = 22 + the target's level. Ignore any armor check penalty and Speed reduction.\n\n- 20 temporary Hit Points.\n\n- Speed 40 feet.\n\n- Low-light vision.\n\n- The following unarmed melee attacks, which are the only attacks the target can use to Strike. When Striking with these attacks, the target uses their attack modifier with the proficiency and item bonuses of their most favorable weapon or unarmed Strike, and the damage is listed for each attack. These attacks are Strength based (for the purpose of the condition, for example).\n- Melee 1 tusk (reach 15 feet), Damage 4d8+19 piercing\n- Melee 1 trunk (agile, reach 15 feet), Damage 4d6+16 bludgeoning\n- Melee 1 foot (agile, reach 15 feet), Damage 4d6+13 bludgeoning.\n\n- Athletics modifier of +30, unless the target's own modifier is higher.\n\n- Each target can use the Trample action.\n- Trample 3 You move up to twice your Speed and move through the space of Large or smaller creatures, trampling each creature whose space you enter. A trampled creature takes damage from your foot Strike based on a basic Reflex save (DC = 19 + your level).","source":{"provider":"PAIZO","sourceId":"pmP8HhXvvEKP3LqU","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.primal-phenomenon","name":"Primal Phenomenon","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You request a direct intercession from the natural world. Nature always refuses unnatural requests and might grant a different request (potentially more powerful or better fitting its character) than the one you asked for. A primal phenomenon spell can do any of the following things.\n\n- Duplicate any spell from the primal spell list of 9th rank or lower to which you have access.\n\n- Duplicate any spell from another spell list of 7th rank or lower. It must be common or you must have access.\n\n- Produce any effect whose power level is in line with the above effects.\n\n- Reverse certain effects that refer to the spell.\n\nAt the GM's discretion, you can try to use primal phenomenon to produce greater effects than these, but doing so may be dangerous, or the spell may have only a partial effect.","source":{"provider":"PAIZO","sourceId":"MLNeD5sAunV0E23j","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.raga-of-remembrance","name":"Raga of Remembrance","kind":"RITUAL","rank":10,"rarity":"UNIQUE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"ceramics, incense, and pigments worth 100,000 gp"},"targeting":{"range":{"kind":"NONE"},"target":"the primary caster","area":null},"duration":{"text":"7 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion (legendary)","secondaryChecks":"Diplomacy or Performance; Nature; Religion or Society","secondaryCasters":3},"description":"You scribe occult symbols on unblighted Vudran ground, laying the ceramics within them to create a ritual space. To perform the ritual, light incense in the ceramics and sit at the center of the ritual space. You then play the disharmonic instrument, drawing on musical skill, occult harmonics, or religious tradition. This establishes an underlying drone atop which the secondary casters layer their own performances. The song calls to the millions who died defending Vudra from Kothogaz, investing their power in Vanitapati, the legendary psychic.\n\nCritical Success A towering, ethereal avatar of Vanitapati manifests around you, surrounded by swirling spirits. The avatar weakens Kothogaz's spirit. While Kothogaz is within 1 mile of you, it is Frightened 2 and is permanently destroyed if reduced to 0 Hit Points.\n\nSuccess As critical success, but Kothogaz is Frightened 1.\n\nFailure The dead come to your aid, but their presence is unnerving. As success, but Kothogaz isn't frightened, and the primary and secondary casters take a -1 status penalty to saving throws against emotion effects.\n\nCritical Failure Rather than the dead, Kothogaz hears the ritual's call and immediately teleports to the primary caster with its Disharmonic Door ability. Primary and secondary casters are afflicted with many-eyed blight.","source":{"provider":"PAIZO","sourceId":"nuE9qsY2HfPFEgAo","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.remake","name":"Remake","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"DISTANCE","feet":5},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fully re-create an object from nothing, even if the object was destroyed. To do so, you must be able to picture the object in your mind. Additionally, the material component must be a remnant of the item, no matter how small or insignificant (even a speck of dust that remains from is enough). The spell fails if your imagination relied on too much guesswork; if the object would be too large to fit in a 5-foot cube; if the object still exists and you were simply not aware of it; or if the object is an artifact, has a level over 20, or has similar vast magical power.\n\nThe item reassembles in perfect condition. Even if your mental image was of a damaged or weathered object, the new one is in this perfected form. If the object was magical, this spell typically restores its constant magical properties, but not any temporary ones, such as charges or one-time uses. An item with charges or uses per day has all of its uses expended when remade, but it replenishes them normally thereafter.","source":{"provider":"PAIZO","sourceId":"dMKP4fkWx8V2cqAy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.revival","name":"Revival","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"dead creatures and living creatures of your choice within range","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"10d8+40","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A burst of healing energy soothes living creatures and temporarily rouses those recently slain. All living targets regain 10d8+40 Hit Points.\n\nIn addition, you return any number of dead targets to life temporarily, with the same effects and limitations as . The raised creatures have a number of temporary Hit Points equal to the Hit Points you gave living creatures, but no normal Hit Points. The raised creatures can't regain Hit Points or gain temporary Hit Points in other ways, and once revival's duration ends, they lose all temporary Hit Points and die.\n\nRevival can't resurrect creatures killed by or a death effect. It has no effect on undead.","source":{"provider":"PAIZO","sourceId":"HpIJTVqgXorH9X0L","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shadow-army","name":"Shadow Army","kind":"SPELL","rank":10,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate","mental","shadow","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":50}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"3d10","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create dozens of semi-real copies of yourself that swarm across the battlefield and fight your enemies. You are virtually indistinguishable from your clones, allowing you to Hide and Sneak among them. An enemy that's in the area when the spell is cast or that ends its turn in the area takes 3d10 mental damage and 3d10 bludgeoning damage, and is possibly inflicted with a condition, depending on the result of its Will save. When you Cast the Spell, you choose a condition your shadows impose on a failed save: Clumsy 2, Enfeebled 2, , or Slowed 1.\n\nCritical Success The creature takes no damage. For the duration of the spell, the creature gets a result one step better than it rolled on further saves against the spell, and can distinguish you from your clones without difficulty.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage, and gains the chosen condition.\n\nCritical Failure The creature takes double damage, and gains the chosen condition.","source":{"provider":"PAIZO","sourceId":"hvKtmoHwekDZ5iOH","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.song-of-the-fallen","name":"Song of the Fallen","kind":"SPELL","rank":10,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 4 dead creatures or up to 4 undead creatures","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You chant a dirge or an elegy that either rouses the dead to action or reminds undead that they should lay to rest.\n\nIf you target dead creatures, the bodies animate and can continue acting as if they were alive. A creature animated in this way has 60 temporary Hit Points. The animated creatures are slowed 1 but can otherwise act normally. Creatures animated with this spell die again once the spell ends.\n\nIf you target undead creatures, each undead must attempt a basic Will save.\n\nCritical Success The undead takes 5d6 vitality damage.\n\nSuccess The undead takes 10d6 vitality damage and is Slowed 1 for 1 round.\n\nFailure The undead takes 100 vitality damage and is Slowed 1 for 1 minute.\n\nCritical Failure The undead is destroyed.","source":{"provider":"PAIZO","sourceId":"IGXGs9PlqUCvODcH","book":"Pathfinder #150: Broken Promises","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-kaiju","name":"Summon Kaiju","kind":"SPELL","rank":10,"rarity":"RARE","traits":["concentrate","incarnate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You briefly conjure a kaiju, a massive, rampaging monster with a unique name and legendary reputation. It rises from its secluded lair to annihilate your foes. The summoned kaiju occupies the space of a Gargantuan creature. When you Cast this Spell, choose one of the kaiju below to summon.\n\n- Agmazar the Star Titan Speed 100 feet, climb 50 feet; Arrive (necromancy, negative) Channel Void Each foe in a 100-foot emanation takes 16d8[void] damage with a basic Fortitude save; Depart (transmutation) Gravitic Repulsion Each foe in a 50-foot emanation is pushed 100 feet away unless it succeeds at a Fortitude save.\n\n- Agyra, the Forever Storm Speed 80 feet, fly 200 feet; Arrive (electricity, evocation) Breath of a Thousand Storms Agyra shoots two 1,200-foot lines of electricity, one from each of her heads. The lines can't overlap. Each creature along one of the lines takes 6d12[electricity] damage with a basic Reflex save. On a failure, the creature is also Slowed 1 for 1 round (or for 1 minute on a critical failure); Depart (evocation, sonic) Thunderous Blast Each creature within a 100-foot emanation takes 6d10[sonic] damage with a basic Reflex save, and is also knocked on a failed save.\n\n- Bezravnis, the Inferno Below Speed 100 feet, burrow 100 feet; Arrive (earth, evocation) Burrow from the Earth's Heart Bezravnis explodes from the ground where it was summoned, causing all creatures in a 50-foot emanation to take 8d12[bludgeoning] damage with a basic Reflex save. This potentially collapses structures with the collapse effect of the spell, except there is no chance of falling into a fissure; Depart Web Hurricane Bezravnis departs with a hurricane of webbing. All creatures within a 50-foot emanation must succeed at a Reflex save or take a –20-foot circumstance penalty to its Speeds until it Escapes (or is until it escapes on a critical failure). The Escape DC is your spell DC.\n\n- Mogaru, the Final King Speed 100 feet, swim 100 feet; Arrive (auditory, enchantment, mental) Trance of the King's Melody Mogaru manifests with a burst of the song that summoned him, requiring all foes within 60 feet who can hear him to attempt a Will save, leaving them Stunned 3 on a failure; Depart (evocation, fire) Volcanic Breath Mogaru unleashes his scorching breath in a 120-foot cone. Each creature in the area takes 10d6[fire] damage with a basic Reflex save. On a failure, it also takes 4d6[persistent,fire] damage.\n\n- Vorgozen, the Shapeless Feeder Speed 50 feet, climb 50 feet, swim 100 feet; Arrive (necromancy) Pollute Magic Vorgozen's foul presence pollutes magic around her. Each of your enemies within a 60-foot emanation that are under the effects of a spell must attempt a Fortitude save. On a failure, the creature is Sickened 2. Any of your enemies that Casts a Spell within 60 feet of Vorgozen must attempt a Fortitude save with the same effects unless it's already sickened; Depart (acid, evocation) Beam of Purest Vitriol Each creature in a 1,200-foot line takes 10d6[acid] damage and 10d6[bludgeoning] damage with a basic Fortitude save.\n\n- Yarthoon, the Moon Grub Speed 60 feet, burrow 100 feet, fly 100 feet, swim 100 feet; Arrive (cold, evocation) Algid Beam Barrage Yarthoon fires countless beams, targeting each of your enemies within 200 feet of it. The beams deal 10d6[cold] damage with a basic Reflex save; Depart (cold, conjuration, water) Frostbite Mist Chilling mist surges out in a 100-foot burst centered on Yarthoon and remains for 1 minute. This mist has the effects of , plus any creature within the area at the end of its turn take 5d6[cold] damage with a basic Fortitude save.\n\n- Ebeshra, the Winged Razor Speed 75 feet, fly 100 feet; Arrive (conjuration, teleportation) Planar Draw Each foe in a is pulled 50 feet towards the center, unless it succeeds at a Fortitude save. Creatures that fail and reach the center take 10d6[bludgeoning] damage; Depart (electricity, evocation) Storm Discharge Each foe in a takes 12d8[electricity] damage with a basic Reflex save.","source":{"provider":"PAIZO","sourceId":"WRP8TDf36hqHyGv1","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
